/* ---------- 後中英文：第 3 週（文法重點與文章） ----------
   每天兩篇文章：[克漏字, 閱讀]。題目格式同第 2 週。 */
WEEKS[2].gram = [
  {
  id: 's.part',
  title: '分詞修飾：V-ing 是主動，V-ed 是被動',
  body: '<p><b>分詞</b>是動詞變成的形容詞，有兩種：<b>現在分詞</b>（V-ing）和<b>過去分詞</b>（V-ed，或不規則的 taken、written…）。分詞片語常放在名詞<b>後面</b>修飾它，就像省略了 who／which 的關係子句。</p>\n<ul><li><b>V-ing＝主動</b>：名詞自己做這個動作。patients <b>taking</b> the drug＝正在吃藥的病人（病人吃藥）。</li>\n<li><b>V-ed＝被動</b>：名詞被別人做這個動作。samples <b>collected</b> from patients＝從病人身上被採集的檢體。</li></ul>\n<p class="ex"><span class="ch s">Patients</span> <span class="ch m">infected with the virus</span> <span class="ch v">develop</span> a fever.　（被病毒感染的病人）</p>\n<ul><li>句尾的<b>「, V-ing…」</b>常表示前面那件事造成的<b>結果</b>：The virus spread quickly, <b>leaving</b> many patients ill.（結果讓很多病人生病）</li></ul>\n<p>判斷三步驟：① 句子已經有主要動詞了嗎？有的話，空格不能再放一個動詞（took、were collected）。② 名詞和這個動作是誰做誰？③ 主動用 V-ing，被動用 V-ed。</p>',
  qs: [
    { id: 'g1-1', sk: 's.part', q: 'Patients ____ the new drug reported fewer migraine attacks than those given a placebo.', o: [ 'taking', 'taken', 'took', 'to be taken' ], why: '主要動詞是 reported，空格不能再放動詞 took。病人「主動」吃藥，用現在分詞 taking；taken 是被動，意思會變成病人被吃。', st: [ [ '句子已經有主要動詞了嗎？', '有，是 reported', '沒有，要填在空格', '有，是 attacks', 'Patients ___ the new drug reported…：reported 是主要動詞，空格只能放修飾 Patients 的分詞。', 's.core' ], [ '病人和吃藥是什麼關係？', '病人主動吃藥', '病人被藥吃掉', '藥主動吃病人', '吃藥的是病人自己，是主動。', 's.part' ], [ '主動的關係，分詞用？', 'V-ing', 'V-ed', '原形動詞', '主動用現在分詞 V-ing：taking。', 's.part' ] ] },
    { id: 'g1-2', sk: 's.part', q: 'The samples ____ from each patient were stored at minus 80 degrees.', o: [ 'collected', 'collecting', 'were collected', 'collect' ], why: '主要動詞是 were stored。檢體是「被」採集的，用過去分詞 collected；were collected 會讓句子出現兩個主要動詞。', st: [ [ '主要動詞是？', 'were stored', 'collected', 'each patient', '檢體被保存在零下 80 度：were stored。', 's.core' ], [ '檢體和採集是什麼關係？', '檢體被人採集', '檢體去採集別人', '檢體自己採集自己', '採集的是醫護人員，檢體是被採集的。', 's.part' ], [ '被動的關係，又不能再放動詞，用？', 'collected', 'collecting', 'were collected', '過去分詞 collected 表示被動，放在名詞後面修飾它。', 's.part' ] ] },
    { id: 'g1-3', sk: 's.part', q: 'The virus spread quickly through the ward, ____ dozens of patients ill within a week.', o: [ 'leaving', 'left', 'to leave', 'leaves' ], why: '逗號前面是完整的句子，逗號後面補充它造成的結果，用「, V-ing」：leaving。leaves 會讓兩個句子只靠逗號連接。', st: [ [ '逗號前面是完整的句子嗎？', '是，主詞和動詞都有', '不是，缺主要動詞', '不是，缺主詞', 'The virus（主詞）spread（動詞）：已經完整。', 's.core' ], [ '逗號後面說的是什麼？', '前面那件事的結果', '前面那件事的原因', '另一件無關的事', '病毒擴散，結果幾十位病人生病。', 'c.logic' ], [ '表示結果的分詞片語，用？', 'leaving', 'left', 'leaves', '句尾的「, V-ing」表示結果；主詞 virus 主動造成這個結果。', 's.part' ] ] }
  ]
},
  {
  id: 'g.tense',
  title: '時態進階：過去式、現在完成式、過去完成式怎麼選',
  body: '<p>研究文章最常用三種過去相關的時態，選法看<b>時間線索</b>：</p>\n<ul><li><b>過去式</b>：過去某個明確的時間點，事情已經結束。in 2018、last year、ago、when the trial ended。</li>\n<li><b>現在完成式</b>（have／has＋過去分詞）：從過去延續到<b>現在</b>，或對現在還有影響。since 2010、for ten years、so far、in recent years。</li>\n<li><b>過去完成式</b>（had＋過去分詞）：<b>過去的過去</b>，比另一件過去的事更早發生。by the time＋過去式、before＋過去式。</li></ul>\n<p class="ex">By the time the trial <span class="ch m">ended</span> in 2020, <span class="ch s">a third of the participants</span> <span class="ch v">had left</span>.　（離開比試驗結束更早）</p>\n<p>選好時態，還要配合主詞的單複數：先找到<b>主詞的中心</b>。the number of patients、the incidence of the infection、each of the variables 是單數；the variables that the team measured 是複數。</p>',
  qs: [
    { id: 'g2-1', sk: 'g.tense', q: 'By the time the trial ended in 2020, more than a third of the participants ____ the study.', o: [ 'had left', 'have left', 'leave', 'are leaving' ], why: 'By the time＋過去式（ended）：離開發生在試驗結束「之前」，是過去的過去，用過去完成式 had left。', st: [ [ 'the trial ended in 2020 是什麼時間？', '過去的一個時間點', '從過去到現在', '未來的一個時間點', 'ended 是過去式，in 2020 是明確的過去。', 'g.tense' ], [ '受試者離開和試驗結束，哪個先？', '離開比較早', '結束比較早', '同時發生', 'By the time…＝到…的時候已經：離開在結束之前就發生了。', 'g.tense' ], [ '比過去更早的事，用什麼時態？', '過去完成式', '現在完成式', '現在進行式', '過去的過去用 had＋過去分詞。', 'g.tense' ] ] },
    { id: 'g2-2', sk: 'g.tense', q: 'Since the new guidelines were introduced, the incidence of the infection ____ steadily.', o: [ 'has fallen', 'fell', 'have fallen', 'falls' ], why: 'Since＋過去的事：從那時到現在，用現在完成式。主詞中心是 incidence（單數），所以用 has fallen。', st: [ [ 'Since… 讓主要子句用什麼時態？', '現在完成式', '過去式', '現在式', 'since＋過去的時間點＝從那時到現在。', 'g.tense' ], [ '主詞的中心是？', 'incidence', 'infection', 'guidelines', 'the incidence of the infection：中心是 incidence。', 'g.tense' ], [ 'incidence 是單數，配？', 'has', 'have', 'are', '單數主詞的現在完成式用 has＋過去分詞。', 'g.tense' ] ] },
    { id: 'g2-3', sk: 'g.tense', q: 'The variables that the team measured in 2019 ____ not consistent with the earlier results.', o: [ 'were', 'was', 'has been', 'is' ], why: '主詞中心是 variables（複數）；that the team measured in 2019 修飾它。說的是 2019 年的測量結果，用過去式 were。', st: [ [ '主詞的中心是？', 'variables', 'the team', 'results', 'that the team measured in 2019 是修飾 variables 的關係子句。', 'g.tense' ], [ 'variables 是單數還是複數？', '複數', '單數', '不一定', '字尾 -s，是 variable 的複數。', 'g.tense' ], [ '說 2019 年的事、主詞複數，用？', 'were', 'was', 'are', '過去的事用過去式，複數主詞配 were。', 'g.tense' ] ] }
  ]
},
  {
  id: 'c.collo',
  title: '固定搭配：形容詞、名詞後面的介系詞要整組記',
  body: '<p><b>固定搭配</b>是英文習慣放在一起的字，介系詞不能靠中文翻譯推，要整組記。上週練了動詞＋介系詞，這週練<b>形容詞與名詞</b>後面的介系詞：</p>\n<ul><li><b>to</b>：prone to（容易…）、susceptible to、detrimental to（對…有害）、conducive to（有助於…）、exposed to／exposure to（接觸到…）、a barrier to（…的阻礙）</li>\n<li><b>with</b>：consistent with（和…一致）、associated with（和…有關）、compared with</li>\n<li><b>for</b>：responsible for、a risk factor for、a treatment for</li>\n<li><b>of</b>：capable of、aware of、a lack of</li></ul>\n<p>因果的兩組最常考：<b>A result in B</b>＝A 造成 B；<b>B result from A</b>＝B 來自 A；<b>A lead to B</b>＝A 導致 B。</p>\n<p class="ex"><span class="ch s">Poor sleep</span> <span class="ch v">can result in</span> weaker immunity.　＝　Weaker immunity <span class="ch v">can result from</span> poor sleep.</p>',
  qs: [
    { id: 'g3-1', sk: 'c.collo', q: 'Workers who are exposed ____ fine dust every day are more likely to develop lung disease.', o: [ 'to', 'with', 'by', 'from' ], why: 'be exposed to＝接觸到、暴露在…之中。', st: [ [ 'exposed 在這裡是什麼意思？', '接觸到、暴露在', '被揭發、被拆穿', '被展示、被陳列', '工人每天吸到粉塵：是接觸到粉塵。', 'v.mean' ], [ '「接觸到…」的固定搭配是？', 'be exposed to', 'be exposed with', 'be exposed from', 'exposed to 和名詞 exposure to 都接 to。', 'c.collo' ] ] },
    { id: 'g3-2', sk: 'c.collo', q: 'Poor diet and lack of sleep can contribute ____ heart disease.', o: [ 'to', 'for', 'with', 'on' ], why: 'contribute to＝促成、是…的原因之一：不良飲食和睡眠不足是心臟病的成因之一。', st: [ [ 'contribute 在這裡的意思？', '是…的原因之一', '把錢捐給…', '和…一起工作', '本週單字 contribute：貢獻；促成。這裡是「促成」。', 'v.mean' ], [ 'contribute 後面接哪個介系詞？', 'to', 'for', 'with', 'contribute to、lead to、prone to 都接 to。', 'c.collo' ] ] },
    { id: 'g3-3', sk: 'c.collo', q: 'Poor sleep can result ____ weaker immunity, which in turn may lead ____ more infections.', o: [ 'in / to', 'from / to', 'in / for', 'from / in' ], why: '睡不好是原因，免疫力變弱是結果：原因 result in 結果。免疫力變弱再導致更多感染：lead to。', st: [ [ 'Poor sleep 和 weaker immunity，哪個是原因？', 'Poor sleep', 'weaker immunity', '兩者沒有關係', '睡不好造成免疫力變弱。', 'c.logic' ], [ '「原因＋result ___＋結果」用？', 'in', 'from', 'to', 'A result in B＝A 造成 B；result from 的後面放原因。', 'c.collo' ], [ '「導致」的 lead 後面接？', 'to', 'in', 'for', 'lead to＝導致。', 'c.collo' ] ] }
  ]
},
  {
  id: 'c.logic',
  title: '前後文邏輯：轉折、因果、舉例、補充四種關係',
  body: '<p>克漏字的轉折語考的是<b>前後兩句的關係</b>。先把兩句各用一句中文說出來，再判斷是哪一種：</p>\n<ul><li><b>轉折（方向相反）</b>：however、nevertheless、yet、on the other hand。</li>\n<li><b>取代（前面否定，後面說真正的情況）</b>：instead、rather、on the contrary。前一句常有 not、no、never。</li>\n<li><b>因果（前面是原因，後面是結果）</b>：therefore、as a result、consequently、thus。</li>\n<li><b>舉例（後面是前面的一個例子）</b>：for example、for instance。</li>\n<li><b>補充（同方向，再加一點）</b>：in addition、moreover、furthermore、also。</li>\n<li><b>換句話說（後面重說一次前面）</b>：in other words、that is。</li></ul>\n<p class="ex">The study did <b>not</b> find a rise in blood pressure. <span class="ch m">Instead,</span> it found a small drop.　（前面否定，後面說實際找到什麼）</p>\n<p>常見陷阱：前後方向相反時，要分清楚是「兩件事都成立」（however）還是「後面取代前面」（instead）。</p>',
  qs: [
    { id: 'g4-1', sk: 'c.logic', q: 'The herb is widely sold as a cure for insomnia. ____, no rigorous trial has shown that it works.', o: [ 'However', 'Therefore', 'For example', 'In addition' ], why: '前一句說它被當成失眠良藥廣泛販售，後一句說沒有嚴謹試驗證明有效：方向相反，兩件事都成立，用 However。', st: [ [ '前一句的意思是？', '它被當成良藥大賣', '它被證明沒有效', '它的價格很便宜', 'is widely sold as a cure：被廣泛當成解藥販售。', 'c.logic' ], [ '後一句的意思是？', '沒有試驗證明它有效', '試驗證明它很有效', '它還有其他好處', 'no rigorous trial has shown that it works。', 'c.logic' ], [ '「大賣」和「沒證據」是什麼關係？', '轉折', '因果', '補充', '兩件事方向相反，又同時成立：用 However。', 'c.logic' ] ] },
    { id: 'g4-2', sk: 'c.logic', q: 'The study did not find that coffee raised blood pressure. ____, it found a small drop in some participants.', o: [ 'Instead', 'For example', 'As a result', 'Similarly' ], why: '前一句否定（沒有發現血壓上升），後一句說實際發現的情況（血壓小幅下降）：後面取代前面，用 Instead。', st: [ [ '前一句有沒有否定？', '有，did not find', '沒有，是肯定句', '有，是 raised blood', 'The study did not find…：沒有發現。', 'c.logic' ], [ '後一句和前一句的關係？', '說出實際發現的情況', '舉出前一句的例子', '說出前一句的結果', '沒發現上升，反而發現下降：後面取代前面。', 'c.logic' ] ] },
    { id: 'g4-3', sk: 'c.logic', q: 'Air pollution harms the lungs. ____, it has been linked to heart disease and dementia.', o: [ 'Moreover', 'However', 'Instead', 'Otherwise' ], why: '前一句說傷肺，後一句再加上心臟病和失智：同方向補充，用 Moreover（此外）。', st: [ [ '後一句和前一句的方向？', '相同：都說污染的壞處', '相反：後面說污染的好處', '後面否定了前面的說法', '傷肺、和心臟病失智有關：都是壞處。', 'c.logic' ], [ '同方向、再加一點，用？', 'Moreover', 'However', 'Instead', 'moreover＝此外、而且。', 'c.logic' ] ] }
  ]
},
  {
  id: 's.noun',
  title: '名詞子句：that、what、whether 讓一整句話當名詞用',
  body: '<p><b>名詞子句</b>是一整個句子當名詞用，可以放在主詞或受詞的位置。三個最常考的開頭：</p>\n<ul><li><b>that＋完整的句子</b>：「…這件事」。that 本身沒有意思，後面什麼都不缺。Many patients do not realize <b>that</b> insomnia can make pain worse.</li>\n<li><b>what＋缺主詞或受詞的句子</b>：what＝the thing that（…的東西）。<b>What</b> patients need most is clear information.（need 後面缺受詞）</li>\n<li><b>whether（或 if）＋完整的句子</b>：「是否…」。<b>Whether</b> the drug works in children is still unknown.</li></ul>\n<p class="ex"><span class="ch s">What surprised the researchers</span> <span class="ch v">was</span> the speed of the decline.　（名詞子句當主詞，動詞用單數）</p>\n<p>判斷兩步驟：① 空格後面的句子缺不缺東西？缺主詞或受詞→ what；完整→ that 或 whether。② 意思是「…這件事」還是「是否…」？</p>',
  qs: [
    { id: 'g5-1', sk: 's.noun', q: '____ the drug can relieve pain in children has not yet been tested.', o: [ 'Whether', 'What', 'Which', 'Because' ], why: '空格後面 the drug can relieve pain 是完整的句子；意思是「這種藥是否能緩解兒童的疼痛」還沒被測試，用 Whether。what 後面要缺東西；Because 開頭的子句不能當主詞。', st: [ [ '空格後面的句子缺東西嗎？', '不缺，句子完整', '缺少一個主詞', '缺少一個受詞', 'the drug（主詞）can relieve（動詞）pain（受詞）：都有。', 's.noun' ], [ '整個名詞子句的意思應該是？', '這種藥是否能緩解疼痛', '這種藥能緩解的東西', '因為這種藥能緩解疼痛', '「還沒被測試」的是「能不能緩解」這個問題。', 's.noun' ], [ '「是否…」用哪個字開頭？', 'Whether', 'What', 'Which', 'whether＝是否，後面接完整的句子。', 's.noun' ] ] },
    { id: 'g5-2', sk: 's.noun', q: '____ surprised the researchers was the speed at which symptoms deteriorated.', o: [ 'What', 'That', 'Whether', 'It' ], why: '空格後面 surprised the researchers 缺主詞；what＝the thing that，整段「讓研究人員驚訝的事」當主詞。', st: [ [ '空格後面的 surprised the researchers 缺什麼？', '缺主詞', '缺受詞', '什麼都不缺', '誰讓研究人員驚訝？主詞不見了。', 's.noun' ], [ '後面缺主詞，名詞子句用？', 'What', 'That', 'Whether', 'what 本身就當子句裡的主詞；that、whether 後面要接完整的句子。', 's.noun' ] ] },
    { id: 'g5-3', sk: 's.noun', q: 'Many patients do not realize ____ insomnia can make chronic pain worse.', o: [ 'that', 'what', 'which', 'whose' ], why: 'realize 後面接一件事當受詞；insomnia can make chronic pain worse 是完整的句子，用 that。', st: [ [ '空格後面的句子缺東西嗎？', '不缺，句子完整', '缺少一個主詞', '缺少一個受詞', 'insomnia（主詞）can make（動詞）chronic pain（受詞）worse。', 's.noun' ], [ '完整的句子當 realize 的受詞，用？', 'that', 'what', 'which', 'that＋完整的句子＝「…這件事」。', 's.noun' ] ] }
  ]
},
  {
  id: 'c.form',
  title: '詞性與形式：看空格的位置，決定要哪一種詞',
  body: '<p>克漏字常把同一個字的四種形式放在選項裡，例如 clear、clearly、clarity、clarify。這時不用想意思，看<b>空格的位置</b>就能選：</p>\n<ul><li><b>名詞</b>：在 a／the／所有格（patients’、his）或形容詞後面，或當主詞、受詞。常見字尾：-tion、-ment、-ity、-ence、-y、-ism。</li>\n<li><b>形容詞</b>：在名詞前面，或在 be 動詞（is、are、seem）後面。常見字尾：-ive、-ous、-al、-ful、-less、-able。</li>\n<li><b>副詞</b>：修飾動詞、形容詞或整句，位置比較自由，拿掉句子仍然完整。常見字尾：-ly。</li>\n<li><b>動詞</b>：主詞後面還缺動詞時。常見字尾：-ize、-ify、-en、-ate。</li></ul>\n<p class="ex">The surgeon <span class="ch v">explained</span> the risks <span class="ch m">clearly</span>.　（修飾動詞 explained，用副詞）</p>',
  qs: [
    { id: 'g6-1', sk: 'c.form', q: 'The new drug ____ reduced the number of hospital visits.', o: [ 'significantly', 'significant', 'significance', 'signify' ], why: 'The new drug reduced the number of hospital visits 已經是完整的句子；空格修飾動詞 reduced（減少得多明顯），要副詞 significantly。', st: [ [ '拿掉空格，句子完整嗎？', '完整', '缺主詞', '缺動詞', 'The new drug（主詞）reduced（動詞）the number（受詞）。', 's.core' ], [ '空格在修飾什麼？', '動詞 reduced', '名詞 drug', '名詞 visits', '說明「減少得多明顯」。', 'c.form' ], [ '修飾動詞用？', '副詞', '形容詞', '名詞', '字尾 -ly 是副詞：significantly。', 'c.form' ] ] },
    { id: 'g6-2', sk: 'c.form', q: 'The surgeon explained the risks ____, so the family fully understood them.', o: [ 'clearly', 'clear', 'clarity', 'clarify' ], why: 'The surgeon explained the risks 已經是完整的句子，空格修飾動詞 explained（怎麼解釋），要副詞 clearly。', st: [ [ '拿掉空格，前半句完整嗎？', '完整', '缺主詞', '缺動詞', 'The surgeon（主詞）explained（動詞）the risks（受詞）。', 's.core' ], [ '空格在修飾什麼？', '動詞 explained', '名詞 the risks', '名詞 the family', '說明「怎麼」解釋：解釋得很清楚。', 'c.form' ], [ '修飾動詞用？', '副詞', '形容詞', '名詞', '副詞修飾動詞，字尾常是 -ly：clearly。', 'c.form' ] ] },
    { id: 'g6-3', sk: 'c.form', q: 'Researchers found no significant ____ between the two groups.', o: [ 'difference', 'differ', 'different', 'differently' ], why: 'significant 是形容詞，後面要接名詞 difference。differ 是動詞（本週單字），different 是形容詞，differently 是副詞。', st: [ [ '空格前面是什麼？', '形容詞 significant', '動詞 found', '名詞 the two groups', 'no significant ___：形容詞後面接名詞。', 'c.form' ], [ '形容詞後面要接？', '名詞', '副詞', '動詞', '形容詞修飾名詞。', 'c.form' ], [ '哪一個是名詞？', 'difference', 'differ', 'different', '字尾 -ence 是名詞；differ 是動詞，different 是形容詞。', 'c.form' ] ] }
  ]
},
  {
  id: 'r.attitude',
  title: '作者態度：從評價字和讓步句看出作者的立場',
  body: '<p>作者態度題問的是作者<b>怎麼看</b>文章裡的事。答案不在某一句的內容，而在作者<b>用了哪些字</b>：</p>\n<ul><li><b>正面</b>：compelling、rigorous、pivotal、promising、encouraging、remarkable</li>\n<li><b>懷疑或負面</b>：ostensibly、so-called、merely、anecdotal、questionable、claim（作者不認同時常用 claim 代替 show）</li>\n<li><b>保留、謹慎</b>：may、might、preliminary、inconclusive、remains unclear、it is too early to…</li></ul>\n<p><b>讓步句</b>常藏著立場：「Although A, B」或「A is not wrong, but B」，作者真正的看法通常在 <b>B</b>。</p>\n<p class="ex"><span class="ch m">Although the preliminary results are encouraging,</span> <span class="ch s">it</span> <span class="ch v">would be</span> premature to change the guidelines.　（作者：謹慎樂觀）</p>\n<p>選項技巧：考題文章的作者通常是<b>平衡、謹慎</b>的；completely、totally、never、proven 這類極端的選項多半是錯的。</p>',
  qs: [
    { id: 'g7-1', sk: 'r.attitude', q: 'The company’s so-called breakthrough is supported only by anecdotal reports. The author’s attitude toward the product is ____.', o: [ 'doubtful', 'enthusiastic', 'neutral', 'admiring' ], why: 'so-called（所謂的）、only by anecdotal reports（只有個案經驗）都表示作者不相信，態度是懷疑的。', st: [ [ 'so-called breakthrough 暗示什麼？', '作者不認為是突破', '作者認為是大突破', '作者沒有任何看法', 'so-called＝所謂的；作者用它表示「別人這麼說，我不這麼認為」。', 'r.attitude' ], [ 'only by anecdotal reports 表示證據如何？', '證據很薄弱', '證據非常充分', '證據來自大試驗', 'only＝只有；anecdotal＝個案經驗：沒有嚴謹的證據。', 'r.attitude' ] ] },
    { id: 'g7-2', sk: 'r.attitude', q: 'Although the preliminary results are encouraging, it would be premature to change the guidelines now. The author is ____.', o: [ 'cautiously hopeful', 'completely opposed', 'strongly convinced', 'totally uninterested' ], why: 'encouraging 是正面，但 preliminary 和 premature（太早的）表示保留：作者謹慎樂觀。', st: [ [ 'encouraging 是正面還是負面？', '正面', '負面', '中立', 'encouraging＝令人振奮的。', 'r.attitude' ], [ 'Although 後面的主要子句說什麼？', '現在改指引太早', '應該馬上改指引', '指引從來不用改', 'it would be premature to change the guidelines now。', 'r.attitude' ], [ '正面但保留，是哪種態度？', '謹慎樂觀', '強烈反對', '完全確信', '承認結果不錯，但不急著下結論。', 'r.attitude' ] ] },
    { id: 'g7-3', sk: 'r.attitude', q: 'In the sentence “The trial, ostensibly independent, was paid for by the drugmaker,” the word “ostensibly” suggests that the author ____.', o: [ 'questions the trial’s independence', 'admires the drugmaker’s support', 'believes the trial was independent', 'has no view on who paid for it' ], why: 'ostensibly＝表面上；後面又說藥廠出錢：作者懷疑這項試驗是否真的獨立。', st: [ [ 'ostensibly 的意思是？', '表面上', '確實地', '偶然地', 'ostensibly＝表面上、名義上，考卷文章常見。', 'v.mean' ], [ '「表面上獨立，卻由藥廠出錢」表示？', '實際上可能不獨立', '試驗完全獨立', '藥廠沒有出錢', '作者用 ostensibly 暗示表裡不一。', 'r.attitude' ] ] }
  ]
}
];
WEEKS[2].passages = [
  // 第 1 天
  [{
  type: 'cloze',
  title: 'Inflammation: Friend and Foe',
  text: [ 'When you cut your finger, the skin around the wound soon becomes red, warm, and swollen. This is inflammation, the body’s first response to injury and infection. Blood vessels near the wound widen, {1} more blood and more immune cells to reach the damaged tissue. These cells attack any pathogens that have entered and begin the work of repair. In this acute form, inflammation is short and useful; it usually ends within a few days once the threat {2} removed.', 'Problems begin when inflammation does not switch off. In chronic inflammation, immune cells keep releasing chemicals that slowly damage healthy cells, {3} there is no longer anything for them to fight. Researchers now believe that this low-level, long-lasting state contributes {4} many common diseases, including heart disease, diabetes, and some cancers. Obesity, smoking, poor sleep, and a sedentary lifestyle can all keep the body in an inflammatory state for years without causing obvious symptoms.', 'This does not mean that all inflammation should be stopped. Drugs that suppress the immune response can relieve pain and swelling, but they may also {5} with the body’s ability to fight infection. Doctors therefore try to treat the cause of chronic inflammation, such as excess weight or smoking, rather than simply hiding its signs. For most people, regular exercise, a moderate diet, and adequate sleep remain the safest ways to keep inflammation under control.' ],
  zh: '手指割傷時，傷口周圍的皮膚很快就會變紅、發熱、腫起來。這就是發炎，身體對受傷和感染的第一個反應。傷口附近的血管擴張，讓更多血液和免疫細胞到達受損的組織。這些細胞攻擊入侵的病原體，並開始修復。在這種急性的形式中，發炎短暫而有用；一旦威脅被清除，通常幾天內就會結束。問題出在發炎關不掉的時候。在慢性發炎中，即使已經沒有東西要對抗，免疫細胞仍不斷釋放化學物質，慢慢傷害健康的細胞。研究人員現在認為，這種低度而長期的狀態，是心臟病、糖尿病和某些癌症等許多常見疾病的成因之一。肥胖、抽菸、睡不好和久坐不動的生活，都可能讓身體多年處於發炎狀態，卻沒有明顯症狀。這並不表示所有的發炎都該被阻止。抑制免疫反應的藥物能減輕疼痛和腫脹，但也可能妨礙身體對抗感染的能力。所以醫生會設法處理慢性發炎的原因，例如過重或抽菸，而不只是把徵兆壓下去。對大多數人來說，規律運動、適量飲食和充足睡眠，仍是控制發炎最安全的方法。',
  qs: [
    { id: 'c1-1', sk: 's.part', q: '第 (1) 格', o: [ 'allowing', 'allowed', 'allows', 'to be allowed' ], why: '逗號前 Blood vessels near the wound widen 是完整的句子，逗號後補充它造成的結果，用「, V-ing」；血管擴張「讓」血液流過去，是主動，所以用 allowing。', st: [ [ '逗號前面是完整的句子嗎？', '是，主詞和動詞都有', '不是，缺主要動詞', '不是，缺主詞', 'Blood vessels（主詞）widen（動詞）。', 's.core' ], [ '逗號後面在說什麼？', '血管擴張帶來的結果', '血管擴張之前的原因', '和血管無關的另一件事', '血管變寬，結果更多血液和免疫細胞能到達。', 'c.logic' ], [ '表示結果的分詞片語，用？', 'allowing', 'allowed', 'allows', '句尾「, V-ing」表示結果；allows 會讓兩個句子只用逗號相連。', 's.part' ] ] },
    { id: 'c1-2', sk: 'g.tense', q: '第 (2) 格', o: [ 'has been', 'have been', 'had been', 'is being' ], why: '威脅是「被」清除的，要用被動；主要子句 it usually ends 是現在式，說一般情況；主詞 the threat 單數，所以用 has been removed（已經被清除）。had been 是過去完成式，和現在式不配。', st: [ [ '主要子句 it usually ends 是什麼時態？', '現在式', '過去式', '未來式', 'usually ends：說一般情況，用現在式。', 'g.tense' ], [ '威脅和清除是什麼關係？', '威脅被清除', '威脅去清除別人', '威脅自己消失', 'removed 是過去分詞，前面要有 be 動詞，形成被動。', 's.pass' ], [ '主詞 the threat 是單數，又要配現在的時間，用？', 'has been', 'have been', 'had been', '單數用 has；had been 是過去完成式，和現在式的 ends 不搭。', 'g.tense' ] ] },
    { id: 'c1-3', sk: 'g.conj', q: '第 (3) 格', o: [ 'even though', 'because', 'so that', 'as long as' ], why: '免疫細胞一直釋放化學物質，但其實已經沒有東西要對抗了：前後方向相反，用 even though（即使）。', st: [ [ '空格前說免疫細胞在做什麼？', '一直釋放化學物質', '停止所有的活動', '正在對抗病原體', 'keep releasing chemicals that slowly damage healthy cells。', 'c.logic' ], [ '空格後說什麼情況？', '已經沒有東西要對抗', '病原體越來越多', '病人開始服藥', 'there is no longer anything for them to fight。', 'c.logic' ], [ '「一直攻擊」和「沒東西可打」是什麼關係？', '相反：不需要卻還在做', '原因：因為沒東西所以攻擊', '目的：為了沒東西才攻擊', '方向相反，用表示讓步的 even though。', 'g.conj' ] ] },
    { id: 'c1-4', sk: 'c.collo', q: '第 (4) 格', o: [ 'to', 'for', 'with', 'from' ], why: 'contribute to＝促成、是…的原因之一：慢性發炎是許多常見疾病的成因之一。', st: [ [ 'contributes 在這裡的意思？', '是…的原因之一', '把錢捐給…', '和…一起工作', '慢性發炎是許多疾病的成因之一。', 'v.mean' ], [ 'contribute 後面接哪個介系詞？', 'to', 'for', 'with', 'contribute to＝促成；和 lead to 一樣接 to。', 'c.collo' ] ] },
    { id: 'c1-5', sk: 'v.collo', q: '第 (5) 格', o: [ 'interfere', 'consist', 'comply', 'cope' ], why: 'interfere with＝干擾、妨礙：抑制免疫的藥可能妨礙身體對抗感染。cope with（應付）、comply with（遵守）也接 with，但意思不通；consist 要接 of。', st: [ [ '抑制免疫的藥，對「對抗感染的能力」有什麼影響？', '讓它變弱', '讓它變強', '完全沒有影響', 'suppress＝壓制；免疫被壓制，對抗感染的能力就變弱。', 'c.logic' ], [ '哪個字＋with 表示「妨礙」？', 'interfere with', 'cope with', 'compete with', 'interfere with＝干擾、妨礙；cope with＝應付；compete with＝競爭。', 'v.collo' ] ] }
  ]
},
   {
  type: 'read',
  title: 'The Virus That Hides',
  text: [ 'Most adults in Taiwan had chickenpox as children. The illness, which causes an itchy rash and a mild fever, usually ends within two weeks, and most people never think about it again. The virus, however, does not leave. After the rash heals, it travels along the nerves and hides inside nerve cells near the spine, where it can stay dormant for decades without causing any symptoms.', 'For about one in three people, the virus eventually becomes active again, usually after the age of fifty. This second illness, called shingles, manifests as a painful band of blisters on one side of the body. The onset is often preceded by burning or tingling in the skin, a feeling that patients sometimes mistake for a heart or stomach problem. Why the virus wakes up is not fully understood, but the risk rises as the immune system weakens with age, stress, or drugs that suppress immunity.', 'For many patients, the rash is not the worst part. In some cases, the pain continues for months or even years after the blisters disappear, because the virus has damaged the nerves. This long-lasting pain can be so severe that it interferes with sleep, work, and daily life, and it is especially common in older adults.', 'The good news is that shingles can largely be prevented. A vaccine approved in 2017 reduces the risk by more than 90 percent in adults over fifty, and its protection appears to last for many years. Health officials in many countries now recommend it for older adults, although its high price remains a barrier for some families. Early antiviral treatment, started within three days of the rash, can also shorten the illness and reduce the chance of lasting pain.' ],
  zh: '台灣大多數成年人小時候都得過水痘。這種病會引起發癢的疹子和輕微發燒，通常兩週內就好了，大多數人之後再也不會想起它。然而病毒並沒有離開。疹子好了之後，它沿著神經移動，躲進脊椎附近的神經細胞裡，可以在那裡潛伏數十年而不引起任何症狀。大約三分之一的人，病毒最後會再度活化，通常是在五十歲以後。這第二種病叫做帶狀皰疹，表現為身體一側一條疼痛的水泡帶。發作前常有皮膚灼熱或刺痛的感覺，病人有時會誤以為是心臟或胃的問題。病毒為什麼會醒來還不完全清楚，但隨著年齡、壓力或抑制免疫的藥物讓免疫系統變弱，風險就會上升。對許多病人來說，疹子還不是最糟的部分。有些情況下，因為病毒損傷了神經，水泡消失後疼痛仍會持續好幾個月甚至好幾年。這種長期的疼痛可能嚴重到干擾睡眠、工作和日常生活，在老年人身上特別常見。好消息是，帶狀皰疹大多可以預防。2017 年核准的一種疫苗能讓五十歲以上成人的風險降低九成以上，保護力似乎能維持很多年。許多國家的衛生官員現在建議老年人接種，不過它的高價格對一些家庭仍是阻礙。在出疹三天內開始的早期抗病毒治療，也能縮短病程、降低長期疼痛的機會。',
  qs: [
    { id: 'r1-1', sk: 'r.main', pre: '主旨：整篇文章最想說的事', q: 'What is the passage mainly about?', o: [ 'How a childhood virus can return later and how to prevent it', 'Why chickenpox is more dangerous for adults than for children', 'How doctors first discovered the cause of chickenpox', 'Why vaccines for older adults are too expensive to use' ], why: '第一段說水痘病毒潛伏在神經裡；第二、三段說它再活化成帶狀皰疹和後遺症；第四段說疫苗和治療。整篇在講這個病毒怎麼回來、怎麼預防。', st: [ [ '第一段說了什麼？', '水痘病毒會潛伏在神經裡', '水痘只會影響兒童', '水痘疫苗的價格很高', 'The virus… hides inside nerve cells… dormant for decades。', 'r.main' ], [ '後面幾段接著說什麼？', '病毒再活化成帶狀皰疹與預防', '水痘病毒是怎麼被發現的', '兒童怎麼在家照顧水痘', '第二到四段：帶狀皰疹的症狀、後遺症、疫苗。', 'r.main' ] ] },
    { id: 'r1-2', sk: 'r.locate', pre: '細節：病毒躲在哪裡', q: 'Where does the chickenpox virus stay after the rash heals?', o: [ 'Inside nerve cells near the spine', 'Inside the skin where the rash was', 'Inside the blood vessels of the heart', 'Inside the stomach and the intestines' ], why: '第一段：it travels along the nerves and hides inside nerve cells near the spine。', st: [ [ '答案在哪一段？', '第一段，疹子好了之後那句', '第二段，三分之一的人那句', '第四段，疫苗核准那句', '題目問疹子好了之後，找 After the rash heals。', 'r.locate' ], [ '病毒躲在哪裡？', '脊椎附近的神經細胞', '原本長疹子的皮膚', '心臟的血管裡', 'hides inside nerve cells near the spine。', 'r.locate' ] ] },
    { id: 'r1-3', sk: 'r.word', pre: '字義：由上下文猜意思', q: 'In paragraph 1, “dormant” is closest in meaning to ____.', o: [ 'inactive', 'harmful', 'visible', 'contagious' ], why: '後面說 for decades without causing any symptoms：幾十年不引起症狀，就是不活動的狀態。', st: [ [ 'dormant 後面怎麼描述病毒？', '幾十年不引起任何症狀', '很快就讓人發高燒', '一直在皮膚上擴散', 'for decades without causing any symptoms。', 'r.word' ], [ '不引起症狀、靜靜待著，最接近？', 'inactive', 'harmful', 'visible', 'inactive＝不活動的；dormant＝休眠的、潛伏的。', 'v.mean' ] ] },
    { id: 'r1-4', sk: 'r.infer', pre: '推論：原文沒有直接說，但可以推出的事', q: 'Why might a patient with early shingles first visit a heart doctor?', o: [ 'The burning feeling can seem like a heart problem.', 'Shingles always begins inside the heart itself.', 'The vaccine is given only by heart doctors.', 'Heart doctors are the only ones who treat rashes.' ], why: '第二段說發作前的灼熱或刺痛，病人有時會誤以為是心臟或胃的問題，所以可能先去看心臟科。', st: [ [ '帶狀皰疹發作前，皮膚有什麼感覺？', '灼熱或刺痛', '冰冷或麻木', '發癢或脫皮', 'The onset is often preceded by burning or tingling in the skin。', 'r.locate' ], [ '原文說病人可能把它誤認成什麼？', '心臟或胃的問題', '普通的感冒', '水痘再次發作', 'patients sometimes mistake for a heart or stomach problem。', 'r.infer' ] ] },
    { id: 'r1-5', sk: 'r.attitude', pre: '作者態度：作者怎麼介紹疫苗', q: 'How does the author present the shingles vaccine?', o: [ 'Highly effective, though cost is a problem for some', 'Useless for adults who are over the age of fifty', 'Too new to be recommended by health officials', 'Effective only if it is given within three days' ], why: '第四段：降低九成以上風險、保護力維持多年（正面），但 its high price remains a barrier for some families（保留）。三天內是抗病毒治療，不是疫苗。', st: [ [ '作者怎麼描述疫苗的效果？', '降低超過九成風險', '只有一點點效果', '效果只維持幾週', 'reduces the risk by more than 90 percent… last for many years。', 'r.locate' ], [ '作者提到疫苗的什麼缺點？', '價格高，有些家庭負擔不起', '副作用多，很少人想打', '只能在三天內接種', 'its high price remains a barrier for some families。', 'r.attitude' ] ] }
  ]
}],
  // 第 2 天
  [{
  type: 'cloze',
  title: 'Why Long Studies Matter',
  text: [ 'Many questions about health cannot be answered in a few months. To learn how habits in childhood affect disease in middle age, researchers need longitudinal studies, which follow the same people for many years. One famous example began in the small town of Framingham, Massachusetts, in 1948. Since then, the study {1} three generations of residents and has produced thousands of research papers.', 'Such studies are expensive and slow, but they can reveal patterns that short studies miss. The Framingham researchers were among the first to show that high blood pressure and smoking raise the risk of heart disease. Before their work, many doctors believed that rising blood pressure was a normal and even necessary part of aging. {2}, they considered it harmless.', 'Long studies also face a special problem: people drop out. Some move away, some lose interest, and some become too ill to continue. If the people {3} leave are different from those who stay, the results can be confounded. For instance, if the sickest participants are the most likely to quit, the remaining group will look healthier than the population it is meant to {4}.', 'Researchers therefore work hard to keep participants in the study, sending reminders, offering free health checks, and even visiting people at home. Even so, they must interpret the final results with care, {5} the group at the end may not be comparable to the group at the start.' ],
  zh: '許多健康問題不是幾個月就能回答的。要知道童年的習慣如何影響中年的疾病，研究人員需要長期追蹤研究，也就是多年追蹤同一群人。一個著名的例子在 1948 年始於美國麻州的小鎮佛明罕。從那時起，這項研究已經追蹤了三代居民，產出了數千篇研究論文。這類研究昂貴又緩慢，但能發現短期研究看不到的模式。佛明罕的研究人員是最早證明高血壓和抽菸會提高心臟病風險的人之一。在他們的研究之前，許多醫生認為血壓上升是老化中正常、甚至必要的一部分。換句話說，他們認為它無害。長期研究也面臨一個特別的問題：有人會退出。有些人搬走，有些人失去興趣，有些人病得太重無法繼續。如果離開的人和留下的人不同，結果就可能被混淆。例如，如果病得最重的受試者最可能退出，剩下的這群人就會比他們本來要代表的族群看起來更健康。因此研究人員努力留住受試者：寄提醒、提供免費健檢，甚至到府拜訪。即使如此，他們解讀最後的結果時仍必須小心，因為最後的那群人可能已經無法和一開始的那群人相比。',
  qs: [
    { id: 'c2-1', sk: 'g.tense', q: '第 (1) 格', o: [ 'has followed', 'followed', 'is following', 'had followed' ], why: 'Since then＝從 1948 年到現在，用現在完成式；後面並列的 has produced 也是現在完成式。主詞 the study 是單數。', st: [ [ 'Since then 的 then 指什麼時候？', '1948 年', '現在這一年', '未來某一年', '前一句：began… in 1948。', 'g.tense' ], [ 'Since then＋到現在，用什麼時態？', '現在完成式', '過去式', '過去完成式', 'since＝從那時到現在；後面的 has produced 也是現在完成式。', 'g.tense' ] ] },
    { id: 'c2-2', sk: 'c.logic', q: '第 (2) 格', o: [ 'In other words', 'On the contrary', 'For example', 'Nevertheless' ], why: '前一句說醫生認為血壓上升是正常的老化，後一句說他們認為它無害：意思一樣，只是換個說法，用 In other words。', st: [ [ '前一句說醫生相信什麼？', '血壓上升是正常的', '血壓上升很危險', '血壓不會隨年齡改變', 'rising blood pressure was a normal… part of aging。', 'c.logic' ], [ '「正常的」和「無害的」是什麼關係？', '同一件事換句話說', '兩件相反的事', '前者是後者的例子', '認為正常＝認為無害；後一句只是重說一次。', 'c.logic' ] ] },
    { id: 'c2-3', sk: 's.rel', q: '第 (3) 格', o: [ 'who', 'whom', 'whose', 'what' ], why: 'the people ___ leave：空格後面缺主詞，先行詞是人，用 who。後面的 those who stay 也是同樣的結構。', st: [ [ '空格後面 leave 缺什麼？', '缺主詞', '缺受詞', '什麼都不缺', '誰離開？主詞不見了。', 's.rel' ], [ '先行詞 the people 是人，缺主詞時用？', 'who', 'whom', 'whose', 'who 指人、當主詞；whom 當受詞；whose 後面要接名詞。', 's.rel' ] ] },
    { id: 'c2-4', sk: 'v.mean', q: '第 (4) 格', o: [ 'represent', 'recruit', 'refute', 'restrict' ], why: '研究的受試者本來是要「代表」整個族群；剩下的人比較健康，就不能代表了。', st: [ [ '剩下的人應該要像誰？', '整個族群', '最健康的人', '研究人員', 'the population it is meant to ___：研究對象本來要代表整個族群。', 'r.locate' ], [ '「代表」的英文是？', 'represent', 'recruit', 'refute', 'recruit＝招募；refute＝反駁；restrict＝限制。', 'v.mean' ] ] },
    { id: 'c2-5', sk: 'g.conj', q: '第 (5) 格', o: [ 'since', 'unless', 'although', 'so that' ], why: '要小心解讀，是「因為」最後那群人可能和一開始的不同。since 在這裡＝because。', st: [ [ '空格前說研究人員要怎麼做？', '小心解讀結果', '放棄整個研究', '加快研究速度', 'they must interpret the final results with care。', 'c.logic' ], [ '空格後是空格前的什麼？', '原因', '讓步', '目的', '最後那群人可能和一開始不同，所以要小心：後面是原因。', 'c.logic' ], [ '表示原因的連接詞是？', 'since', 'unless', 'although', 'since 在這裡＝because。', 'g.conj' ] ] }
  ]
},
   {
  type: 'read',
  title: 'Does Coffee Protect the Liver?',
  text: [ 'Over the past twenty years, dozens of studies have reported that people who drink coffee are less likely to develop liver disease. In one large study that followed nearly 500,000 adults in Britain for about eleven years, coffee drinkers were about 20 percent less likely to develop chronic liver disease and about half as likely to die from it. The pattern appeared for ground coffee and, to a lesser degree, for instant coffee as well.', 'The finding is plausible. Coffee contains hundreds of compounds, and in animal studies some of them reduce inflammation and slow the build-up of scar tissue in the liver. Yet the human evidence comes almost entirely from observational studies, in which researchers simply record what people choose to drink. Such studies can show a correlation, but they cannot prove that coffee is the cause.', 'The main problem is that coffee drinkers may differ from non-drinkers in other ways. People who feel unwell often give up coffee, and heavy drinkers of alcohol, who face a high risk of liver disease, may prefer other drinks. Researchers try to adjust for such factors, but they can never measure everything. A hidden difference could confound the result.', 'For now, most experts describe the evidence as encouraging but inconclusive. A long randomized trial, in which some people are told to drink coffee and others to avoid it, would give a clearer answer, but it would be difficult and expensive to run. Until then, doctors do not tell patients to start drinking coffee for the sake of their livers. For people who already enjoy two or three cups a day, however, there seems to be no reason to stop.' ],
  zh: '過去二十年，有幾十項研究報告喝咖啡的人比較不容易得肝病。在一項追蹤英國近五十萬名成人約十一年的大型研究中，喝咖啡的人得慢性肝病的機率少了約兩成，死於肝病的機率約只有一半。研磨咖啡有這個模式，即溶咖啡也有，只是程度較小。這個發現似乎合理。咖啡含有數百種化合物，在動物研究中，其中一些能減少發炎、減緩肝臟中疤痕組織的累積。然而人類的證據幾乎全部來自觀察性研究，研究人員只是記錄人們選擇喝什麼。這類研究能顯示相關，卻不能證明咖啡就是原因。主要的問題是，喝咖啡的人可能在其他方面和不喝的人不同。覺得不舒服的人常會戒咖啡；而肝病風險很高的酗酒者，可能偏好其他飲料。研究人員會設法校正這些因素，但永遠無法測量所有東西。一個隱藏的差異就可能混淆結果。目前，大多數專家形容這些證據令人鼓舞但沒有定論。一項長期的隨機分派試驗，讓一些人喝咖啡、另一些人不喝，能給出更清楚的答案，但執行起來既困難又昂貴。在那之前，醫生不會為了肝臟叫病人開始喝咖啡。不過，對已經每天喜歡喝兩三杯的人來說，似乎也沒有理由停下來。',
  qs: [
    { id: 'r2-1', sk: 'r.main', pre: '主旨：整篇文章最想說的事', q: 'What is the main idea of the passage?', o: [ 'Coffee may protect the liver, but the evidence is not yet certain.', 'Coffee causes liver disease in people who drink a lot of alcohol.', 'Instant coffee is healthier for the liver than ground coffee is.', 'A randomized trial has proven that coffee protects the liver.' ], why: '第一段說喝咖啡的人比較少得肝病；第二、三段說這只是相關，可能被其他因素混淆；最後一段說證據 encouraging but inconclusive。', st: [ [ '第一段說了什麼？', '喝咖啡的人比較少得肝病', '咖啡會嚴重傷害肝臟', '即溶咖啡比研磨的健康', 'coffee drinkers are less likely to develop liver disease。', 'r.main' ], [ '最後一段怎麼總結證據？', '令人鼓舞，但還沒有定論', '已經被大型試驗證實', '完全沒有參考的價值', 'encouraging but inconclusive。', 'r.main' ] ] },
    { id: 'r2-2', sk: 'r.locate', pre: '細節：找出正確的數字', q: 'In the British study, how much less likely were coffee drinkers to develop chronic liver disease?', o: [ 'About 20 percent', 'About 50 percent', 'About 11 percent', 'About 5 percent' ], why: '第一段：about 20 percent less likely to develop chronic liver disease。「一半」是死於肝病的數字，11 是追蹤的年數。', st: [ [ '答案在哪一段？', '第一段，英國研究那句', '第二段，似乎合理那句', '第四段，隨機試驗那句', '題目問英國的研究，找 Britain。', 'r.locate' ], [ '「得慢性肝病」對應的是哪一段文字？', 'about 20 percent less likely', 'about half as likely to die', 'for about eleven years', 'about 20 percent less likely to develop chronic liver disease；half 是死亡的數字。', 'r.locate' ] ] },
    { id: 'r2-3', sk: 'r.para', pre: '換句話說：哪個選項和原文那句意思一樣', q: 'Which is closest in meaning to “Such studies can show a correlation, but they cannot prove that coffee is the cause”?', o: [ 'The studies find a link but not a cause.', 'The studies prove that coffee is harmful.', 'The studies show no link of any kind.', 'The studies were too short to find anything.' ], why: 'correlation＝相關（兩件事一起出現）；cannot prove… the cause＝不能證明是原因。', st: [ [ 'correlation 的意思是？', '兩件事一起出現', '一件事造成另一件', '兩件事完全無關', 'correlation＝相關，不等於因果。', 'v.mean' ], [ 'cannot prove that coffee is the cause 表示？', '不能證明是咖啡造成', '已經證明咖啡造成', '咖啡和肝病無關', 'cause＝原因。', 'r.para' ] ] },
    { id: 'r2-4', sk: 'r.infer', pre: '推論：原文沒有直接說，但可以推出的事', q: 'Why might people who feel unwell make coffee look more protective than it really is?', o: [ 'They quit coffee, so more sick people end up among non-drinkers.', 'They drink more coffee, so the coffee group looks sicker.', 'They refuse to join studies, so no sick people are included.', 'They drink only instant coffee, which has fewer compounds.' ], why: '第三段：覺得不舒服的人常會戒咖啡。他們被算進不喝咖啡的那組，讓那組看起來比較不健康，咖啡就顯得有保護作用。', st: [ [ '覺得不舒服的人會怎麼做？', '常常不再喝咖啡', '開始喝更多咖啡', '拒絕參加研究', 'People who feel unwell often give up coffee。', 'r.locate' ], [ '他們會被算進哪一組？', '不喝咖啡的那組', '喝咖啡的那組', '不會被算進去', '不喝咖啡了，就被歸到不喝的那組，讓那組看起來比較不健康。', 'r.infer' ] ] },
    { id: 'r2-5', sk: 'r.attitude', pre: '作者態度：作者會怎麼建議', q: 'How would the author most likely answer a coffee drinker who asks whether to stop?', o: [ 'There is no need to stop.', 'You should stop at once.', 'You should drink twice as much.', 'Coffee will cure liver disease.' ], why: '最後一句：For people who already enjoy two or three cups a day… there seems to be no reason to stop。', st: [ [ '最後一句對已經在喝的人說什麼？', '似乎沒有理由停', '應該馬上停', '應該多喝一點', 'there seems to be no reason to stop。', 'r.attitude' ], [ '作者有沒有建議不喝的人開始喝？', '沒有', '有，每天三杯', '有，為了保護肝', 'doctors do not tell patients to start drinking coffee。', 'r.attitude' ] ] }
  ]
}],
  // 第 3 天
  [{
  type: 'cloze',
  title: 'The Air Inside Your Home',
  text: [ 'When people think of air pollution, they usually picture traffic and factories. Yet for many families, the most serious exposure happens at home. Cooking with gas or burning wood releases fine particles and gases {1} can travel deep into the lungs. In small kitchens with poor airflow, the level of these particles during cooking can be higher than on a busy street.', 'Children and older adults are especially prone {2} the effects. Studies in several countries have linked cooking smoke to asthma in children and to lung disease in adults who have never smoked. In Taiwan, researchers have suggested that years of frying food in poorly ventilated kitchens may help explain why lung cancer is surprisingly common among women who do not smoke.', 'The good news is that the risk can be mitigated with simple changes. Using a range hood every time you cook, opening a window, and keeping a lid on the pan can all {3} the amount of smoke that people breathe in. Switching from a gas stove to an electric one reduces emissions {4}, although not every family can afford a new stove.', 'Cleaner indoor air also brings benefits that go beyond the lungs. Fine particles can pass from the lungs into the blood and exert harmful effects on blood vessels and the heart, {5} cutting exposure at home may protect the heart as well as the lungs. For families who cook every day, these small habits may matter more than they realize.' ],
  zh: '人們想到空氣污染時，通常會想到交通和工廠。然而對許多家庭來說，最嚴重的暴露發生在家裡。用瓦斯煮飯或燒柴會釋放出能深入肺部的細懸浮微粒和氣體。在通風不良的小廚房裡，煮飯時這些微粒的濃度可能比繁忙的街道還高。兒童和老年人特別容易受到影響。好幾個國家的研究都把炊煙和兒童氣喘、以及從不抽菸的成人肺病連結在一起。在台灣，研究人員認為，多年在通風不良的廚房裡炒炸食物，或許能解釋為什麼肺癌在不抽菸的女性中出奇地常見。好消息是，簡單的改變就能降低風險。每次煮飯都開抽油煙機、打開窗戶、蓋上鍋蓋，都能減少人們吸進的油煙。把瓦斯爐換成電爐能大幅減少排放，不過不是每個家庭都買得起新爐子。更乾淨的室內空氣，好處也不只在肺部。細懸浮微粒能從肺進入血液，對血管和心臟造成有害的影響，所以減少在家中的暴露，可能同時保護心臟和肺。對每天煮飯的家庭來說，這些小習慣可能比他們以為的更重要。',
  qs: [
    { id: 'c3-1', sk: 's.rel', q: '第 (1) 格', o: [ 'that', 'what', 'where', 'they' ], why: '空格後面 can travel deep into the lungs 缺主詞；先行詞是 fine particles and gases（物），用 that。用 they 會讓兩個句子沒有連接詞。', st: [ [ '空格後面 can travel deep into the lungs 缺什麼？', '缺主詞', '缺受詞', '什麼都不缺', '誰能深入肺部？主詞不見了。', 's.rel' ], [ '先行詞是什麼？', 'particles and gases', 'gas or burning wood', 'the deep lungs', '能深入肺部的是微粒和氣體。', 's.rel' ], [ '先行詞是物、缺主詞，用？', 'that', 'what', 'they', 'that／which 指物當主詞；用 they 會讓兩個句子沒有連接詞。', 's.rel' ] ] },
    { id: 'c3-2', sk: 'c.collo', q: '第 (2) 格', o: [ 'to', 'of', 'for', 'with' ], why: 'be prone to＝容易受…影響、容易有…。', st: [ [ 'prone 的意思是？', '容易受…影響的', '對…有幫助的', '和…相同的', 'prone＝易於…的、容易…的。', 'v.mean' ], [ 'prone 後面接哪個介系詞？', 'to', 'of', 'with', 'be prone to＋名詞。', 'c.collo' ] ] },
    { id: 'c3-3', sk: 'v.mean', q: '第 (3) 格', o: [ 'reduce', 'release', 'recruit', 'reveal' ], why: '前一句說風險可以降低（mitigated）；開抽油煙機、開窗、蓋鍋蓋都能「減少」吸進的油煙。', st: [ [ '抽油煙機、開窗、蓋鍋蓋，對油煙有什麼作用？', '讓吸進的煙變少', '讓吸進的煙變多', '讓煙變得看得見', '這些是「降低風險」的方法（前一句 mitigated）。', 'c.logic' ], [ '「減少」的英文是？', 'reduce', 'release', 'reveal', 'release＝釋放；reveal＝揭露；recruit＝招募。', 'v.mean' ] ] },
    { id: 'c3-4', sk: 'c.form', q: '第 (4) 格', o: [ 'substantially', 'substantial', 'substance', 'substantiate' ], why: 'Switching… reduces emissions 已經是完整的句子，空格說明「減少多少」，修飾動詞 reduces，要副詞 substantially（大幅地）。', st: [ [ '拿掉空格，reduces emissions 完整嗎？', '完整', '缺受詞', '缺動詞', '主詞 Switching…，動詞 reduces，受詞 emissions。', 's.core' ], [ '空格在修飾什麼？', '動詞 reduces', '名詞 emissions', '名詞 stove', '說明「減少多少」：大幅減少。', 'c.form' ], [ '修飾動詞用？', '副詞', '形容詞', '名詞', '副詞字尾 -ly：substantially。', 'c.form' ] ] },
    { id: 'c3-5', sk: 'g.conj', q: '第 (5) 格', o: [ 'so', 'but', 'although', 'unless' ], why: '微粒會傷害血管和心臟（原因），所以減少暴露也能保護心臟（結果），用 so。', st: [ [ '空格前說微粒會做什麼？', '傷害血管和心臟', '只停留在肺裡', '讓肺變得更強壯', 'exert harmful effects on blood vessels and the heart。', 'c.logic' ], [ '空格後說減少暴露能怎樣？', '同時保護心臟和肺', '只能保護肺', '反而傷害心臟', 'cutting exposure at home may protect the heart as well as the lungs。', 'c.logic' ], [ '前面是原因、後面是結果，用？', 'so', 'but', 'although', '微粒傷心臟，所以減少暴露也保護心臟。', 'g.conj' ] ] }
  ]
},
   {
  type: 'read',
  title: 'Should You Exercise When the Air Is Dirty?',
  text: [ 'Doctors encourage almost everyone to exercise, and many people choose to walk, run, or cycle outdoors. In cities with heavy traffic, however, this advice raises a difficult question. During exercise, people breathe faster and more deeply, so they take in far more polluted air than they would while sitting still. Could the harm from the air offset the benefits of the exercise?', 'To answer this question, researchers in Britain used data on air pollution in cities around the world. They calculated how long a person would have to cycle before the damage from breathing polluted air began to outweigh the gains from exercise. In most cities, the answer was reassuring: a person would need to cycle for many hours every day before the balance tipped. Only in the most polluted cities, where fine particles reach extremely high levels, did the harm appear after about half an hour.', 'Later studies have reached similar conclusions. In a Danish study of more than 50,000 adults, people who cycled or played sports regularly had a lower risk of death than those who did not, even if they lived in areas with more traffic pollution.', 'Experts therefore say that, for most people, giving up exercise is far more detrimental than breathing city air. They do, however, suggest some sensible steps. Exercising in parks or on quiet streets rather than beside main roads can lower exposure considerably. On days when pollution is unusually high, it is wise to exercise indoors or to choose lighter activity. People with asthma or heart disease, who are more sensitive to polluted air, should check the daily air quality before going out.' ],
  zh: '醫生鼓勵幾乎每個人運動，很多人選擇在戶外走路、跑步或騎腳踏車。然而在交通繁忙的城市，這個建議引出一個難題。運動時呼吸更快、更深，所以吸進的污染空氣比坐著不動時多得多。空氣造成的傷害，會不會抵銷運動的好處？為了回答這個問題，英國的研究人員使用了世界各城市的空氣污染資料。他們計算一個人要騎多久的腳踏車，吸入污染空氣的傷害才會開始大於運動的收穫。在大多數城市，答案令人安心：一個人每天要騎好幾個小時，天平才會傾斜。只有在細懸浮微粒極高、污染最嚴重的城市，大約半小時後壞處就出現了。後來的研究得到類似的結論。在一項超過五萬名成人的丹麥研究中，規律騎腳踏車或運動的人，死亡風險比不運動的人低，即使他們住在交通污染較多的地區也一樣。所以專家說，對大多數人來說，放棄運動遠比呼吸城市空氣更有害。不過他們也提出一些合理的做法。在公園或安靜的街道運動，而不是在大馬路旁，能大幅減少暴露。污染特別嚴重的日子，最好在室內運動或選擇較輕的活動。對污染空氣比較敏感的氣喘或心臟病患者，出門前應該先查看當天的空氣品質。',
  qs: [
    { id: 'r3-1', sk: 'r.main', pre: '主旨：整篇文章最想說的事', q: 'What is the main idea of the passage?', o: [ 'For most people, outdoor exercise is still worth it despite pollution.', 'Exercising in cities is more dangerous than not exercising at all.', 'Cycling causes most of the air pollution found in big cities.', 'People with asthma should never exercise outside their homes.' ], why: '第一段提出問題，第二、三段的研究都顯示運動的好處通常大於污染的傷害，最後一段說放棄運動更有害，再加上一些預防做法。', st: [ [ '第一段提出什麼問題？', '污染會不會抵銷運動的好處', '運動要做多久才算夠', '騎腳踏車會不會造成污染', 'Could the harm from the air offset the benefits of the exercise?', 'r.main' ], [ '最後一段的結論是？', '對多數人，不運動更有害', '所有人都應該停止運動', '只有公園裡才能運動', 'giving up exercise is far more detrimental than breathing city air。', 'r.main' ] ] },
    { id: 'r3-2', sk: 'r.locate', pre: '細節：找出時間', q: 'According to the British researchers, when did the harm appear in the most polluted cities?', o: [ 'After about half an hour of cycling', 'After many hours of cycling every day', 'After about one week of cycling', 'After about ten minutes of walking' ], why: '第二段最後一句：Only in the most polluted cities… did the harm appear after about half an hour。「好幾小時」說的是大多數城市。', st: [ [ '答案在哪一段？', '第二段，最污染城市那句', '第三段，丹麥研究那句', '第四段，氣喘患者那句', '題目問最污染的城市，找 most polluted。', 'r.locate' ], [ '在那些城市，多久之後壞處出現？', 'about half an hour', 'many hours a day', 'about a full day', 'did the harm appear after about half an hour。', 'r.locate' ] ] },
    { id: 'r3-3', sk: 'r.word', pre: '字義：由上下文猜意思', q: 'In paragraph 2, “the balance tipped” most likely means that ____.', o: [ 'the harm became greater than the benefit', 'the harm and the benefit stayed equal', 'the benefit became clear to everyone', 'the air pollution was finally measured' ], why: '前一句說要算多久之後傷害開始大於收穫（outweigh the gains）；天平「傾斜」就是壞處超過好處。', st: [ [ 'the balance 指的是什麼的平衡？', '好處和壞處', '收入和支出', '速度和距離', '前一句：damage… began to outweigh the gains。', 'r.word' ], [ '天平傾斜之後會怎樣？', '壞處開始大於好處', '好處和壞處一樣', '兩者都消失了', 'balance tipped＝天平傾向另一邊。', 'r.word' ] ] },
    { id: 'r3-4', sk: 'r.infer', pre: '推論：原因是什麼', q: 'Why do people take in more pollution while exercising?', o: [ 'They breathe faster and more deeply.', 'Exercise itself makes the air dirtier.', 'They usually exercise near factories.', 'Their lungs become smaller as they run.' ], why: '第一段：During exercise, people breathe faster and more deeply, so they take in far more polluted air。', st: [ [ '原文說運動時呼吸有什麼變化？', '更快、更深', '更慢、更淺', '完全沒有變化', 'people breathe faster and more deeply。', 'r.locate' ], [ '呼吸變快變深，結果是？', '吸進更多污染空氣', '吸進更少污染空氣', '空氣變得比較乾淨', 'they take in far more polluted air than they would while sitting still。', 'r.infer' ] ] },
    { id: 'r3-5', sk: 'r.attitude', pre: '作者態度：作者對戶外運動的看法', q: 'What is the author’s attitude toward outdoor exercise in cities?', o: [ 'Supportive, with some sensible precautions', 'Strongly against it in every large city', 'Uncertain, because no studies have been done', 'Indifferent to the risks of breathing pollution' ], why: '作者引用研究說好處通常大於傷害，又列出在公園運動、查空氣品質等做法：支持，但要注意。', st: [ [ '作者對大多數人的建議是？', '繼續運動', '停止運動', '只在室內運動', 'giving up exercise is far more detrimental。', 'r.attitude' ], [ '作者還提出什麼？', '一些合理的預防做法', '運動的危險遠大於好處', '不需要注意空氣品質', 'They do, however, suggest some sensible steps。', 'r.attitude' ] ] }
  ]
}],
  // 第 4 天
  [{
  type: 'cloze',
  title: 'The Four-Day Week',
  text: [ 'For more than a century, most office employees have worked five days a week. In recent years, however, a growing number of companies have tested a four-day week, {1} staff work fewer hours for the same pay. Supporters argue that rested workers make fewer mistakes, take fewer sick days, and are less likely to quit. Some also believe that a longer weekend gives parents more time with their children.', 'The largest trial so far took place in Britain in 2022 and involved about 2,900 employees at 61 companies. At the end of six months, most of the companies {2} to keep the new schedule. Workers reported less stress and better sleep. {3}, the number of sick days fell by about two thirds. The companies’ income, meanwhile, stayed roughly the same.', 'Critics, however, point out that the results may not apply to every kind of work. The companies in the trial chose to take part, so their managers were probably more enthusiastic than average. It is also much harder to shorten the week in hospitals, schools, and factories, where staff must be present {4} patients, students, and machines need attention every day.', 'For now, the four-day week seems most {5} for office jobs, where results can be measured more easily than hours worked. Whether it can spread to other industries will depend on whether managers are willing to rethink the way they organize work. Some firms have also tried a shorter working day instead of a shorter week.' ],
  zh: '一百多年來，大多數辦公室員工每週工作五天。然而近年來，越來越多公司試行每週四天的工作制，員工工作時數變少，薪水卻不變。支持者主張，休息充足的員工犯錯較少、請病假較少，也比較不會離職。也有人認為，較長的週末讓父母有更多時間陪孩子。目前最大的試驗於 2022 年在英國進行，有 61 家公司約 2,900 名員工參與。六個月結束時，大多數公司決定保留新的工作制。員工表示壓力變小、睡得更好。此外，病假天數減少了約三分之二。同時，公司的收入大致維持不變。然而，批評者指出，這些結果未必適用於每一種工作。參與試驗的公司是自己選擇加入的，所以這些公司的主管可能比一般人更熱衷。在醫院、學校和工廠縮短工作週也困難得多，因為病人、學生和機器每天都需要照顧，員工必須在場。目前看來，每週四天最適合辦公室工作，因為那裡的成果比工時更容易衡量。它能否推廣到其他行業，要看主管是否願意重新思考安排工作的方式。也有些公司改試縮短每天的工時，而不是縮短工作週。',
  qs: [
    { id: 'c4-1', sk: 's.rel', q: '第 (1) 格', o: [ 'in which', 'which', 'what', 'whose' ], why: '空格後面 staff work fewer hours for the same pay 是完整的句子，說明「在這種工作制裡」：in which＝in a four-day week。只用 which 會少了介系詞；what 不能接在名詞後面。', st: [ [ '空格後面的句子缺東西嗎？', '不缺，句子完整', '缺少一個主詞', '缺少一個受詞', 'staff（主詞）work（動詞）fewer hours：完整。', 's.rel' ], [ '員工「在哪裡」工作較少時數？', '在四天工作制裡', '在公司的大樓裡', '在英國的試驗裡', '空格指的是前面的 a four-day week。', 's.rel' ], [ '「在＋先行詞（物）」的關係子句用？', 'in which', 'which', 'whose', '介系詞＋which；後面是完整的句子。', 's.rel' ] ] },
    { id: 'c4-2', sk: 'g.tense', q: '第 (2) 格', o: [ 'decided', 'deciding', 'decide', 'to decide' ], why: '空格是 most of the companies 的主要動詞；At the end of six months 說的是 2022 年試驗結束時，過去的事，用過去式 decided。', st: [ [ '這個句子有主要動詞嗎？', '沒有，要填在空格', '有，是 keep', '有，是 took place', 'to keep 是不定詞，不是主要動詞。', 's.core' ], [ '說的是什麼時候的事？', '2022 年試驗結束', '現在這週正在發生', '要到未來才會發生', '前一句：The largest trial… took place in Britain in 2022。', 'g.tense' ], [ '過去的事、當主要動詞，用？', 'decided', 'deciding', 'decide', '過去式 decided；V-ing 和 to＋原形都不能當主要動詞。', 'g.tense' ] ] },
    { id: 'c4-3', sk: 'c.logic', q: '第 (3) 格', o: [ 'In addition', 'However', 'Instead', 'Otherwise' ], why: '前一句是好消息（壓力小、睡得好），後一句又是好消息（病假變少）：同方向補充，用 In addition。', st: [ [ '空格前一句說什麼？', '壓力變小、睡得更好', '壓力變大、睡不好', '收入大幅下降', 'Workers reported less stress and better sleep。', 'c.logic' ], [ '空格後一句說什麼？', '病假減少三分之二', '病假增加了一倍', '員工紛紛離職', 'the number of sick days fell by about two thirds。', 'c.logic' ], [ '兩個好消息是什麼關係？', '補充', '轉折', '取代', '同方向、再加一點：In addition。', 'c.logic' ] ] },
    { id: 'c4-4', sk: 'g.conj', q: '第 (4) 格', o: [ 'because', 'although', 'unless', 'so that' ], why: '員工必須在場，是「因為」病人、學生和機器每天都需要照顧。', st: [ [ '空格前說什麼？', '員工必須在場', '員工可以在家', '員工可以少做', 'staff must be present。', 'c.logic' ], [ '空格後是空格前的什麼？', '原因', '讓步', '目的', '每天都需要照顧，所以必須在場：後面是原因。', 'c.logic' ], [ '表示原因的連接詞？', 'because', 'although', 'unless', 'although＝雖然；unless＝除非。', 'g.conj' ] ] },
    { id: 'c4-5', sk: 'v.mean', q: '第 (5) 格', o: [ 'suitable', 'severe', 'moral', 'fatal' ], why: '四天工作制「最適合」辦公室工作，因為成果容易衡量。', st: [ [ '後面說辦公室工作有什麼特點？', '成果容易衡量', '工作非常危險', '員工都很年輕', 'where results can be measured more easily than hours worked。', 'r.locate' ], [ '所以四天工作制對辦公室工作是？', '最合適的', '最嚴重的', '最致命的', 'suitable＝合適的；severe＝嚴重的；fatal＝致命的；moral＝道德的。', 'v.mean' ] ] }
  ]
},
   {
  type: 'read',
  title: 'The Power of Habits',
  text: [ 'Every morning, millions of people reach for their phones before they get out of bed. Few of them decide to do so; the action happens almost automatically. Most of us are not even aware of how many of our daily actions are really habits. Psychologists estimate that about 40 percent of what we do each day is driven by habit rather than by conscious choice.', 'A habit forms when a behavior is repeated many times in the same situation. Each time, the brain links three things: a cue, such as waking up; a routine, such as checking messages; and a reward, such as the small pleasure of seeing something new. After enough repetition, the cue alone is enough to trigger the routine, even if the reward is no longer very satisfying.', 'This explains why good intentions often fail. People who want to eat better or exercise more typically rely on willpower, but willpower tends to be weakest when we are tired or stressed, which is exactly when old habits take over. Studies suggest that it takes about two months of daily repetition, on average, before a new behavior becomes automatic, although the time varies widely from person to person. Missing a single day, however, does not appear to ruin the process.', 'Researchers therefore recommend changing the situation rather than fighting it. Keeping fruit on the kitchen table, putting running shoes by the door, or leaving the phone in another room at night can make the desired behavior easier and the old one harder. In other words, the most successful people may not have more self-control than others; they may simply have arranged their lives so that they need it less.' ],
  zh: '每天早上，數百萬人還沒下床就伸手拿手機。很少人是決定要這麼做的；這個動作幾乎是自動發生的。我們大多數人甚至沒有察覺，日常的行為有多少其實是習慣。心理學家估計，我們每天做的事大約有四成是由習慣驅動，而不是有意識的選擇。當一個行為在同樣的情境中重複很多次，習慣就形成了。每一次，大腦都把三件事連在一起：提示，例如醒來；例行動作，例如查看訊息；以及獎勵，例如看到新東西的小小樂趣。重複夠多次之後，光是提示就足以觸發例行動作，即使獎勵已經不太令人滿足。這解釋了為什麼好的意圖常常失敗。想吃得更健康或多運動的人通常依靠意志力，但意志力往往在我們疲累或有壓力時最薄弱，而那正是舊習慣接手的時候。研究顯示，新的行為平均要每天重複大約兩個月才會變成自動的，不過所需時間因人而異，差別很大。不過，偶爾漏掉一天似乎不會毀掉整個過程。因此研究人員建議改變情境，而不是和它對抗。把水果放在廚房桌上、把跑鞋放在門邊，或晚上把手機放在別的房間，都能讓想要的行為變容易、舊的行為變困難。換句話說，最成功的人未必比別人更有自制力；他們可能只是把生活安排得比較不需要自制力。',
  qs: [
    { id: 'r4-1', sk: 'r.main', pre: '主旨：整篇文章最想說的事', q: 'What is the main idea of the passage?', o: [ 'Habits form through repetition and are easier to change by changing the situation.', 'Willpower is the most effective way to break a bad habit quickly.', 'Most people check their phones in the morning because they are bored.', 'Every new habit takes exactly two months to form for every person.' ], why: '第二段說習慣怎麼形成，第三段說意志力為什麼常失敗，第四段建議改變情境：主旨是習慣靠重複形成、靠改變情境來改。', st: [ [ '第二段在說什麼？', '習慣怎麼形成', '手機怎麼設計', '睡眠怎麼影響情緒', 'A habit forms when a behavior is repeated many times in the same situation。', 'r.main' ], [ '最後一段的建議是？', '改變情境，而不是硬撐', '多靠意志力撐下去', '完全不要使用手機', 'Researchers therefore recommend changing the situation rather than fighting it。', 'r.main' ] ] },
    { id: 'r4-2', sk: 'r.locate', pre: '細節：找出數字', q: 'According to psychologists, about how much of our daily behavior is driven by habit?', o: [ 'About 40 percent', 'About 60 percent', 'About 80 percent', 'About 20 percent' ], why: '第一段：about 40 percent of what we do each day is driven by habit。', st: [ [ '答案在哪一段？', '第一段，Psychologists estimate 那句', '第三段，Studies suggest 那句', '第四段，Researchers recommend 那句', '題目問心理學家的估計，找 Psychologists estimate。', 'r.locate' ], [ '數字是？', '40 percent', 'two months', 'three things', 'about 40 percent of what we do each day。', 'r.locate' ] ] },
    { id: 'r4-3', sk: 'r.word', pre: '字義：由上下文猜意思', q: 'In paragraph 2, “trigger” is closest in meaning to ____.', o: [ 'start', 'stop', 'hide', 'reward' ], why: '光是提示就足以讓例行動作「開始」。trigger＝觸發、引發（第 2 週學過）。', st: [ [ 'the cue alone is enough to trigger the routine：提示出現後，例行動作會？', '開始發生', '完全停止', '被隱藏起來', '醒來（提示）就會去看訊息（例行動作）。', 'r.word' ], [ '最接近 trigger 的字是？', 'start', 'stop', 'hide', 'trigger＝觸發、引發。', 'v.mean' ] ] },
    { id: 'r4-4', sk: 'r.infer', pre: '推論：原文沒有直接說，但可以推出的事', q: 'Why might a very tired person eat unhealthy snacks despite planning not to?', o: [ 'Willpower is weakest then, so old habits take over.', 'Tired people need more sugar than others do.', 'Habits only form when people are very tired.', 'The cue disappears completely when people are tired.' ], why: '第三段：willpower tends to be weakest when we are tired or stressed, which is exactly when old habits take over。', st: [ [ '第三段說意志力什麼時候最弱？', '疲累或有壓力的時候', '早上剛睡醒的時候', '吃飽飯休息的時候', 'willpower tends to be weakest when we are tired or stressed。', 'r.locate' ], [ '意志力弱的時候會發生什麼？', '舊習慣接手', '新習慣自動形成', '提示完全消失', 'which is exactly when old habits take over。', 'r.infer' ] ] },
    { id: 'r4-5', sk: 'r.attitude', pre: '作者態度：作者怎麼看意志力', q: 'How does the author view relying on willpower to change habits?', o: [ 'As less effective than changing the situation', 'As the only reliable way to change habits', 'As harmful to both the body and the mind', 'As something that most people completely lack' ], why: '作者說好的意圖常常失敗，因為意志力在疲累時最弱；最後建議改變情境，並說成功的人只是不太需要自制力。', st: [ [ '作者說好的意圖常常怎樣？', '失敗', '成功', '被遺忘', 'This explains why good intentions often fail。', 'r.attitude' ], [ '作者比較推薦哪種方法？', '改變周圍的情境', '更用力地忍耐', '請別人監督自己', 'recommend changing the situation rather than fighting it。', 'r.attitude' ] ] }
  ]
}],
  // 第 5 天
  [{
  type: 'cloze',
  title: 'Cities and Heat',
  text: [ 'On a summer afternoon, the center of a large city can be several degrees hotter than the countryside {1} it. This effect, known as the urban heat island, occurs because roads and buildings absorb heat during the day and release it slowly at night. Air conditioners make the problem worse, since they push hot air out into the streets.', 'The extra heat is more than uncomfortable. During heat waves, death rates rise sharply, especially among older adults {2} live alone. Doctors have found that many of these deaths could be prevented with simple measures, such as cooling centers and regular phone calls to people at risk. People who take certain medications, such as some drugs for blood pressure, are also at higher risk, because the drugs can affect how the body controls its temperature.', 'Cities are now experimenting with ways to cool themselves down. Some have painted roofs white so that they reflect sunlight {3} absorbing it. Others are planting trees along streets, because shade and the water released from leaves can lower the temperature of the surrounding air by several degrees.', 'Such measures are not expensive, but they work best when they are combined. A single park cannot cool an entire district, while a network of green spaces, light-colored roofs, and shaded streets can. As summers become {4} hot, experts warn that cities which fail to adapt will pay a high price, {5} in money and in lives.' ],
  zh: '夏日午後，大城市的市中心可能比周圍的鄉間熱好幾度。這種現象稱為都市熱島效應，原因是道路和建築物白天吸收熱，晚上再慢慢釋放出來。冷氣讓問題更嚴重，因為它把熱空氣排到街上。多出來的熱不只是讓人不舒服。熱浪期間死亡率急遽上升，尤其是獨居的老年人。醫生發現，其中許多死亡可以靠簡單的措施預防，例如設置避暑中心、定期打電話給高風險的人。服用某些藥物的人，例如一些降血壓藥，風險也比較高，因為這些藥會影響身體調節體溫的方式。各城市現在正在嘗試讓自己降溫的方法。有些城市把屋頂漆成白色，讓屋頂反射陽光而不是吸收陽光。有些在街道兩旁種樹，因為樹蔭和葉子釋放的水分能讓周圍空氣的溫度降低好幾度。這些措施並不昂貴，但結合起來效果最好。一座公園無法讓整個區域降溫，而由綠地、淺色屋頂和有遮蔭的街道組成的網絡就可以。隨著夏天越來越熱，專家警告，無法適應的城市將付出高昂的代價，在金錢和人命上都是。',
  qs: [
    { id: 'c5-1', sk: 's.part', q: '第 (1) 格', o: [ 'surrounding', 'surrounded', 'surrounds', 'to surround' ], why: '空格修飾 the countryside：鄉間「圍繞著」城市，是主動，用現在分詞 surrounding。句子的主要動詞已經是 can be，不能再用 surrounds。', st: [ [ '句子的主要動詞是？', 'can be', 'surrounds', 'hotter', 'the center of a large city can be several degrees hotter…', 's.core' ], [ '鄉間和城市是什麼關係？', '鄉間圍繞著城市', '鄉間被城市圍繞', '城市圍繞著鄉間', 'the countryside ___ it：it 指城市，鄉間在城市周圍。', 's.part' ], [ '名詞主動做這個動作，分詞用？', 'surrounding', 'surrounded', 'surrounds', '主動用 V-ing：surrounding。', 's.part' ] ] },
    { id: 'c5-2', sk: 's.rel', q: '第 (2) 格', o: [ 'who', 'which', 'whose', 'where' ], why: 'older adults ___ live alone：空格後面缺主詞，先行詞是人，用 who。', st: [ [ '空格後面 live alone 缺什麼？', '缺主詞', '缺受詞', '什麼都不缺', '誰獨居？主詞不見了。', 's.rel' ], [ '先行詞是人、缺主詞，用？', 'who', 'which', 'whose', 'who 指人當主詞；which 指物；whose 後面要接名詞。', 's.rel' ] ] },
    { id: 'c5-3', sk: 'c.logic', q: '第 (3) 格', o: [ 'instead of', 'as well as', 'because of', 'in addition to' ], why: '白色屋頂反射陽光，「而不是」吸收陽光：instead of＋V-ing。', st: [ [ '白色屋頂對陽光做什麼？', '反射它', '吸收它', '又反射又吸收', 'they reflect sunlight。', 'c.logic' ], [ '「反射」和「吸收」是什麼關係？', '一個取代另一個', '兩個同時發生', '一個是另一個的原因', '漆成白色就是為了不吸收熱：用 instead of（而不是）。', 'c.logic' ] ] },
    { id: 'c5-4', sk: 'c.form', q: '第 (4) 格', o: [ 'increasingly', 'increase', 'increasing', 'increased' ], why: 'become ___ hot：空格修飾形容詞 hot（熱的程度越來越高），要副詞 increasingly（本週單字）。', st: [ [ '空格後面的 hot 是什麼詞性？', '形容詞', '名詞', '動詞', 'become hot＝變熱；hot 是形容詞。', 'c.form' ], [ '修飾形容詞用？', '副詞', '形容詞', '名詞', '副詞可以修飾形容詞：越來越熱。', 'c.form' ], [ '哪一個是副詞？', 'increasingly', 'increasing', 'increase', '字尾 -ly：increasingly＝越來越。', 'c.form' ] ] },
    { id: 'c5-5', sk: 's.para', q: '第 (5) 格', o: [ 'both', 'either', 'neither', 'not only' ], why: '空格後面是 in money and in lives，用 and 連接，成對的是 both A and B。either 要配 or，neither 要配 nor，not only 要配 but also。', st: [ [ '空格後面用哪個字連接兩部分？', 'and', 'or', 'nor', 'in money and in lives。', 's.para' ], [ '和 and 成對的是？', 'both', 'either', 'neither', 'both A and B；either A or B；neither A nor B。', 's.para' ] ] }
  ]
},
   {
  type: 'read',
  title: 'Will Machines Take Our Jobs?',
  text: [ 'Every major advance in technology has raised the same fear: that machines will replace human workers. In the early 1800s, weavers in England smashed the new machines that threatened their jobs. Two centuries later, similar concerns surround artificial intelligence, which can now write reports, translate languages, and identify diseases in medical images.', 'History suggests that the fear is partly justified but often exaggerated. Machines have indeed destroyed many jobs, from telephone operators to factory workers. At the same time, new technologies have created entire industries that no one could have imagined, such as app design and online marketing. Bank tellers, for instance, did not disappear when cash machines arrived; banks simply opened more branches and gave tellers new tasks. Over the long term, the share of adults with jobs has not fallen, even as machines have become far more capable.', 'What makes artificial intelligence different, some economists argue, is the kind of work it can perform. Earlier machines mainly replaced physical tasks, while AI can handle tasks that require reading, writing, and judgment, the kind of work done by office employees, lawyers, and even doctors. A 2023 study estimated that about 80 percent of American workers could see at least some of their tasks affected.', 'Yet “affected” does not necessarily mean “replaced.” In many cases, AI may take over the most boring parts of a job and leave workers more time for tasks that require human contact. A radiologist who uses AI to check routine scans, for instance, can spend more time on difficult cases. The real challenge, experts say, is making sure that workers have the chance to learn new skills before their old ones become unnecessary.' ],
  zh: '每一次重大的科技進步，都引發同樣的恐懼：機器會取代人類勞工。1800 年代初，英國的織工砸毀了威脅他們工作的新機器。兩個世紀後，類似的擔憂圍繞著人工智慧；它現在能寫報告、翻譯語言，還能從醫學影像中辨認疾病。歷史顯示，這種恐懼部分有道理，但常常被誇大。機器確實消滅了許多工作，從電話接線生到工廠工人。同時，新科技也創造了沒人能想像的整個產業，例如應用程式設計和網路行銷。舉例來說，自動提款機出現後，銀行櫃員並沒有消失；銀行只是開了更多分行，並給櫃員新的工作。長期來看，有工作的成人比例並沒有下降，即使機器已經變得能幹得多。有些經濟學家主張，人工智慧的不同之處在於它能做的工作種類。早期的機器主要取代體力工作，而 AI 能處理需要閱讀、寫作和判斷的工作，也就是辦公室員工、律師甚至醫生所做的工作。2023 年的一項研究估計，約八成美國勞工的工作中至少有一部分會受到影響。然而，「受影響」不一定代表「被取代」。在許多情況下，AI 可能接手工作中最無聊的部分，讓勞工有更多時間處理需要與人接觸的事。例如，用 AI 檢查例行影像的放射科醫師，就能把更多時間花在困難的病例上。專家說，真正的挑戰是確保勞工在舊技能變得多餘之前，有機會學習新技能。',
  qs: [
    { id: 'r5-1', sk: 'r.main', pre: '主旨：整篇文章最想說的事', q: 'What is the main idea of the passage?', o: [ 'AI will change many jobs, but history suggests it may not simply destroy them.', 'AI has already replaced most office employees, lawyers, and doctors.', 'Weavers in England were the first people to use artificial intelligence.', 'Economists agree that machines have greatly reduced the number of jobs.' ], why: '作者用歷史說明恐懼常被誇大，再說 AI 會影響很多工作，但「受影響」不等於「被取代」。', st: [ [ '第二段說歷史顯示什麼？', '恐懼部分有道理但常被誇大', '機器從來沒有消滅過工作', '恐懼完全正確', 'the fear is partly justified but often exaggerated。', 'r.main' ], [ '最後一段的重點是？', '受影響不等於被取代', 'AI 會取代所有醫生', 'AI 比人類更有同理心', '“affected” does not necessarily mean “replaced.”', 'r.main' ] ] },
    { id: 'r5-2', sk: 'r.locate', pre: '細節：研究估計了什麼', q: 'What did the 2023 study estimate?', o: [ 'About 80 percent of US workers may see some tasks affected.', 'About 80 percent of US workers will soon lose their jobs.', 'About 80 percent of new jobs are now in app design.', 'About 80 percent of doctors already use AI every day.' ], why: '第三段：about 80 percent of American workers could see at least some of their tasks affected。是「部分工作受影響」，不是失業。', st: [ [ '答案在哪一段？', '第三段，A 2023 study 那句', '第二段，Over the long term 那句', '第四段，A radiologist 那句', '題目問 2023 年的研究，找 2023。', 'r.locate' ], [ 'some of their tasks affected 的意思是？', '部分工作內容受影響', '全部工作都會消失', '工作時數會增加', 'at least some of their tasks：至少一部分的工作內容。', 'r.locate' ] ] },
    { id: 'r5-3', sk: 'r.para', pre: '換句話說：哪個選項和原文那句意思一樣', q: 'Which is closest in meaning to “the fear is partly justified but often exaggerated”?', o: [ 'The worry has some basis, but it is usually too strong.', 'The worry is completely wrong and has no basis at all.', 'The worry is fully correct and should grow even stronger.', 'The worry was reasonable only in the early 1800s.' ], why: 'partly justified＝部分有道理；exaggerated＝誇大的。', st: [ [ 'partly justified 的意思是？', '部分有道理', '完全沒道理', '完全正確', 'partly＝部分地；justified＝有正當理由的。', 'r.para' ], [ 'exaggerated 的意思是？', '被誇大的', '被低估的', '被證實的', 'exaggerate＝誇大。', 'r.para' ] ] },
    { id: 'r5-4', sk: 'r.infer', pre: '推論：作者為什麼舉這個例子', q: 'Why does the author mention radiologists?', o: [ 'To show how AI can help workers rather than replace them', 'To prove that doctors will soon lose their jobs to AI', 'To explain how AI was first invented for use in hospitals', 'To argue that routine scans are no longer needed at all' ], why: '放射科醫師用 AI 檢查例行影像，就有更多時間處理困難病例：例子支持「AI 接手無聊的部分、讓人做更需要人的事」。', st: [ [ '這個例子在哪一段？', '最後一段，受影響不等於被取代', '第一段，英國織工砸毀新機器', '第二段，電話接線生失去工作', 'for instance 前面一句：AI may take over the most boring parts of a job。', 'r.locate' ], [ '放射科醫師用了 AI 之後怎樣？', '有更多時間看困難病例', '很快就失去了工作', '不再需要親自看影像', 'can spend more time on difficult cases。', 'r.infer' ] ] },
    { id: 'r5-5', sk: 'r.attitude', pre: '作者態度：作者對 AI 與工作的看法', q: 'What is the author’s attitude toward AI and jobs?', o: [ 'Cautiously optimistic', 'Deeply fearful', 'Completely indifferent', 'Strongly hostile' ], why: '作者認為恐懼常被誇大、AI 可能幫助勞工（樂觀），但也提醒真正的挑戰是讓勞工學新技能（謹慎）。', st: [ [ '作者怎麼看「機器搶工作」的恐懼？', '常常被誇大', '完全正確', '完全不存在', 'partly justified but often exaggerated。', 'r.attitude' ], [ '作者有沒有提出擔憂？', '有，要讓勞工學新技能', '沒有，完全不擔心', '有，主張禁止 AI', 'The real challenge… is making sure that workers have the chance to learn new skills。', 'r.attitude' ] ] }
  ]
}],
  // 第 6 天
  [{
  type: 'cloze',
  title: 'Learning Words from Reading',
  text: [ 'Most of the words we know were never taught to us directly. Instead, we picked them up while reading or listening, {1} their meanings from the context. Researchers estimate that a reader who meets an unknown word in a book has only about a one-in-ten chance of learning it from that single encounter.', 'That chance may sound small, but it adds up. A student who reads for twenty minutes a day meets roughly a million words a year, and many of them are unfamiliar. Over several years, regular reading can expand vocabulary far more {2} than memorizing lists alone, and the words are learned together with the way they are actually used. This is one reason why heavy readers tend to have larger vocabularies.', 'There is, however, an important limit. Learning from context works well only when a reader already understands most of the surrounding words. Studies suggest that readers need to know about 95 percent of the words on a page {3} guess the rest correctly. When too many words are unknown, the context itself becomes unclear, and readers {4} to give up.', 'For learners of a foreign language, this means that reading and studying words should go together. Learning the most common words first makes texts easier to understand, and easier texts {5} more words to be learned from context. Graded readers, which are books written with a limited vocabulary, are designed for exactly this purpose. Each activity supports the other.' ],
  zh: '我們認得的字大多數從來沒有人直接教過。我們是在閱讀或聽的時候學到的，從上下文猜出它們的意思。研究人員估計，讀者在書裡遇到一個不認得的字，光靠那一次接觸學會它的機會只有大約十分之一。這個機會聽起來很小，但會累積。一個每天讀二十分鐘的學生，一年大約會遇到一百萬個字，其中很多是不熟悉的。幾年下來，規律閱讀擴大字彙的效果遠比只背單字表好，而且這些字是連同實際的用法一起學到的。這也是常閱讀的人字彙量往往比較大的原因之一。不過，這有一個重要的限制。從上下文學字，只有在讀者已經看懂周圍大部分的字時才有效。研究顯示，讀者需要認得一頁中大約 95% 的字，才能正確猜出其餘的字。不認得的字太多時，上下文本身就變得不清楚，讀者往往會放棄。對學外語的人來說，這表示閱讀和背單字應該並行。先學最常見的字能讓文章比較容易看懂，而比較容易的文章又讓更多的字能從上下文中學會。分級讀物，也就是用有限字彙寫成的書，正是為了這個目的而設計的。兩種活動相輔相成。',
  qs: [
    { id: 'c6-1', sk: 's.part', q: '第 (1) 格', o: [ 'guessing', 'guessed', 'guess', 'to be guessed' ], why: '逗號前 we picked them up while reading 是完整的句子；逗號後補充「我們怎麼學到」，主詞 we 主動去猜，用現在分詞 guessing。', st: [ [ '逗號前面是完整的句子嗎？', '是，主詞和動詞都有', '不是，缺主要動詞', '不是，缺主詞', 'we（主詞）picked up（動詞）them（受詞）。', 's.core' ], [ '是誰在猜意思？', '我們讀者', '單字本身', '老師', '我們從上下文猜意思，是主動。', 's.part' ], [ '主動、補充說明的分詞片語，用？', 'guessing', 'guessed', 'guess', '主動用 V-ing；guess 會讓兩個動詞沒有連接詞。', 's.part' ] ] },
    { id: 'c6-2', sk: 'c.form', q: '第 (2) 格', o: [ 'effectively', 'effective', 'effect', 'effectiveness' ], why: 'regular reading can expand vocabulary far more ___：空格修飾動詞 expand（擴大得多有效），要副詞 effectively。', st: [ [ '空格在修飾什麼？', '動詞 expand', '名詞 vocabulary', '名詞 lists', '說明「怎麼擴大」：更有效地擴大。', 'c.form' ], [ '修飾動詞用？', '副詞', '形容詞', '名詞', '副詞字尾 -ly：effectively。', 'c.form' ] ] },
    { id: 'c6-3', sk: 'c.logic', q: '第 (3) 格', o: [ 'in order to', 'so as', 'such that', 'in case' ], why: '認得 95% 的字，是「為了」能正確猜出其餘的字：in order to＋原形動詞。so as 少了 to；such that 後面要接句子；in case＝以防。', st: [ [ '認得 95% 和猜出其餘的字是什麼關係？', '前者是為了做到後者', '前者是後者的結果', '兩者方向相反', '要先認得大部分，才猜得出剩下的：表示目的。', 'c.logic' ], [ '空格後面是原形動詞 guess，表示目的用？', 'in order to', 'so as', 'such that', 'in order to／so as to＋原形動詞；so as 少了 to。', 'c.logic' ] ] },
    { id: 'c6-4', sk: 'v.mean', q: '第 (4) 格', o: [ 'tend', 'refer', 'vary', 'rely' ], why: 'readers tend to give up＝讀者往往會放棄。tend to＋原形動詞（本週單字）。refer、rely 後面不接 to＋原形動詞；vary 是「變化」。', st: [ [ '上下文變得不清楚時，讀者會怎樣？', '往往會放棄', '一定會讀完', '開始查字典', 'the context itself becomes unclear, and readers ___ to give up。', 'c.logic' ], [ '「往往會…」的英文是？', 'tend to', 'refer to', 'rely to', 'tend to do＝往往會做…。refer to＝提到；rely on＝依賴。', 'v.mean' ] ] },
    { id: 'c6-5', sk: 'g.tense', q: '第 (5) 格', o: [ 'allow', 'allows', 'allowing', 'allowed' ], why: '主詞是 easier texts（複數），是主要動詞，說一般的事實，用現在式複數 allow。', st: [ [ '這個子句的主詞是？', 'easier texts', 'more words', 'context', 'and 後面：easier texts ___ more words to be learned…', 'g.tense' ], [ 'texts 是單數還是複數？', '複數', '單數', '不一定', 'text 加 s 是複數。', 'g.tense' ], [ '複數主詞、現在式，用？', 'allow', 'allows', 'allowing', '複數主詞的動詞不加 s；allowing 不能當主要動詞。', 'g.tense' ] ] }
  ]
},
   {
  type: 'read',
  title: 'The Silk Road',
  text: [ 'For more than 1,500 years, a network of trade routes connected China with the Mediterranean world. Known today as the Silk Road, it was not a single road but a broad web of paths across deserts, mountains, and seas. Few merchants ever traveled its full length; instead, goods passed from trader to trader and from city to city, often changing hands dozens of times along the way.', 'Silk was the most famous product, but the trade involved far more. Paper, tea, and porcelain moved west, while glass, horses, and silver moved east. Equally important were the things that could not be loaded onto camels. Religions such as Buddhism spread along the routes, as did new techniques in farming, medicine, and mathematics. Some historians argue that ideas, not goods, were the Silk Road’s most lasting contribution.', 'The routes also carried disease. In the fourteenth century, the plague known as the Black Death is believed to have traveled west along trade paths, killing perhaps a third of Europe’s population within a few years. Other diseases, including smallpox and measles, also moved along the routes, reaching people who had no immunity to them. The same connections that brought wealth and knowledge also made distant societies more vulnerable.', 'The trade declined after the fifteenth century, when European ships found sea routes to Asia that were faster and cheaper, and some cities that had grown rich from the trade slowly emptied. Yet the idea of the Silk Road has never disappeared. Today, governments use the name to describe new railways and ports, and historians use it as an early example of globalization, with both its benefits and its dangers.' ],
  zh: '一千五百多年來，一個貿易路線網絡把中國和地中海世界連接起來。這條今天稱為絲路的路線，並不是單一的一條路，而是橫越沙漠、山脈和海洋的一大片路徑網。很少商人走完全程；貨物是從一個商人傳到另一個商人、從一座城市到另一座城市，一路上常常轉手幾十次。絲綢是最有名的商品，但貿易的內容遠不止於此。紙、茶和瓷器往西運，玻璃、馬匹和白銀往東運。同樣重要的是無法裝上駱駝的東西。佛教等宗教沿著這些路線傳播，農業、醫學和數學的新技術也是。有些歷史學家主張，絲路最持久的貢獻是思想，而不是貨物。這些路線也帶來了疾病。十四世紀，被稱為黑死病的瘟疫據信是沿著貿易路線向西傳播，在短短幾年內奪走了歐洲大約三分之一的人口。天花、麻疹等其他疾病也沿著這些路線傳播，傳到對它們沒有免疫力的人群中。帶來財富和知識的同一套連結，也讓遙遠的社會變得更脆弱。十五世紀以後，歐洲船隻找到更快、更便宜通往亞洲的海路，這項貿易就衰退了，有些靠貿易致富的城市也漸漸沒落。然而，絲路的概念從未消失。今天，各國政府用這個名稱來描述新的鐵路和港口，歷史學家則把它當作全球化的早期例子，有好處也有危險。',
  qs: [
    { id: 'r6-1', sk: 'r.main', pre: '主旨：整篇文章最想說的事', q: 'What is the passage mainly about?', o: [ 'How the Silk Road spread goods, ideas, and disease between East and West', 'How Chinese emperors built a single road all the way to Europe', 'Why silk was the only product traded between China and Europe', 'Why the Black Death forced all trade on the Silk Road to stop' ], why: '第一段介紹絲路，第二段說貨物和思想，第三段說疾病，第四段說衰退和今天的意義。', st: [ [ '第二段說絲路傳播了什麼？', '貨物和思想', '只有絲綢', '只有宗教', 'Paper, tea… Religions such as Buddhism spread… new techniques…', 'r.main' ], [ '第三段又說它傳播了什麼？', '疾病', '鐵路', '船隻', 'The routes also carried disease。', 'r.main' ] ] },
    { id: 'r6-2', sk: 'r.locate', pre: '細節：哪些貨物往東運', q: 'Which goods moved east along the Silk Road?', o: [ 'Glass, horses, and silver', 'Paper, tea, and porcelain', 'Silk, paper, and spices', 'Camels, tea, and gold' ], why: '第二段：Paper, tea, and porcelain moved west, while glass, horses, and silver moved east。', st: [ [ '答案在哪一段？', '第二段，moved west／east 那句', '第一段，Mediterranean 那句', '第四段，railways 那句', '找 moved east。', 'r.locate' ], [ 'while 後面那一半說的是？', '往東運的東西', '往西運的東西', '無法運送的東西', 'while glass, horses, and silver moved east。', 'r.locate' ] ] },
    { id: 'r6-3', sk: 'r.word', pre: '字義：由上下文猜意思', q: 'In paragraph 1, “changing hands” means ____.', o: [ 'passing to a new owner', 'being broken into pieces', 'being carried by hand', 'losing all of their value' ], why: '前面說貨物從一個商人傳到另一個商人：changing hands＝換了主人、轉手。', st: [ [ '前面怎麼描述貨物的移動？', '從一個商人傳到另一個商人', '同一個商人從頭運到尾', '用大船直接運到歐洲', 'goods passed from trader to trader。', 'r.word' ], [ '所以 changing hands 是？', '轉到新的主人手上', '一路都用手搬運', '在路上被打成碎片', 'hands 在這裡代表擁有它的人。', 'r.word' ] ] },
    { id: 'r6-4', sk: 'r.infer', pre: '推論：原文沒有直接說，但可以推出的事', q: 'What can be inferred about most merchants on the Silk Road?', o: [ 'They traveled only part of the network.', 'They traveled from China to Europe and back.', 'They were sailors who used European ships.', 'They carried ideas rather than any goods.' ], why: '第一段：Few merchants ever traveled its full length; instead, goods passed from trader to trader。大多數商人只走其中一段。', st: [ [ '原文說有多少商人走完全程？', '很少', '大多數', '全部', 'Few merchants ever traveled its full length。', 'r.locate' ], [ '所以大多數商人？', '只走一部分路線', '走完全程再回來', '只走海路', 'few＝很少；大多數人沒有走完全程。', 'r.infer' ] ] },
    { id: 'r6-5', sk: 'r.attitude', pre: '作者態度：作者怎麼呈現絲路的影響', q: 'How does the author present the effects of the Silk Road?', o: [ 'As both helpful and harmful', 'As entirely positive for everyone', 'As mostly harmful to Europe', 'As unimportant to world history' ], why: '作者既說它帶來財富、知識和宗教，也說它傳播瘟疫；最後一句 with both its benefits and its dangers。', st: [ [ '作者提到絲路帶來哪些好處？', '財富、知識和新技術', '只有疾病和戰爭', '沒有提到任何好處', 'The same connections that brought wealth and knowledge…', 'r.attitude' ], [ '最後一句怎麼總結？', '有好處也有危險', '幾乎只有好處', '幾乎只有危險', 'with both its benefits and its dangers。', 'r.attitude' ] ] }
  ]
}],
  // 第 7 天
  [{
  type: 'cloze',
  title: 'Why Some Species Survive',
  text: [ 'About 99 percent of all the species that have ever lived on Earth are now extinct. The ones that remain are not necessarily the strongest or the most intelligent. {1}, they are the ones that were best able to adapt when their environment changed.', 'Consider the peppered moth in England. Before the industrial era, most of these moths were light in color, {2} helped them hide on pale tree bark. When smoke from factories darkened the trees in the 1800s, dark moths became harder for birds to see, and within a few decades they {3} the most common form in many cities. Birds, meanwhile, ate the light moths that now stood out against the dark bark.', 'The story did not end there. After clean-air laws were introduced in the 1950s, the trees grew lighter again, and so did the moths. Scientists regard the case as one of the clearest examples of natural selection ever observed {4} a human lifetime.', 'Today, many species face changes far faster than any they have met before, from rising temperatures to the loss of forests. Species that reproduce quickly and can live in a broad range of conditions, such as rats and pigeons, tend to do well. Those that depend on a single habitat or a single source of food are far more {5} to extinction. Scientists warn that the coming century may bring a wave of extinctions unlike any in human history.' ],
  zh: '地球上曾經存在過的物種，大約 99% 現在都已經滅絕。留下來的並不一定是最強或最聰明的；而是在環境改變時最能適應的。以英國的樺尺蛾為例。工業時代以前，這種蛾大多是淺色的，這讓牠們能躲在淺色的樹皮上。1800 年代工廠的煙把樹變黑之後，深色的蛾比較不容易被鳥看見，幾十年內，深色蛾在許多城市已經成為最常見的類型。同時，鳥吃掉了在深色樹皮上變得顯眼的淺色蛾。故事並沒有到此結束。1950 年代實施清淨空氣法之後，樹又變淺了，蛾也跟著變淺。科學家把這個案例視為在一個人的一生之內觀察到的天擇最清楚的例子之一。今天，許多物種面臨的變化遠比過去任何一次都快，從氣溫上升到森林消失都是。繁殖快、能在各種環境生存的物種，例如老鼠和鴿子，往往過得不錯。依賴單一棲地或單一食物來源的物種，則容易滅絕得多。科學家警告，接下來這個世紀可能會出現人類史上前所未見的滅絕潮。',
  qs: [
    { id: 'c7-1', sk: 'c.logic', q: '第 (1) 格', o: [ 'Instead', 'Moreover', 'For example', 'Therefore' ], why: '前一句否定（不一定是最強或最聰明的），後一句說真正的情況（最能適應的）：後面取代前面，用 Instead。', st: [ [ '前一句有沒有否定？', '有，not necessarily', '沒有，是肯定句', '有，are now extinct', 'The ones that remain are not necessarily the strongest…', 'c.logic' ], [ '後一句和前一句的關係？', '說出真正的情況', '舉出前一句的例子', '說出前一句的結果', '不是最強的，而是最能適應的。', 'c.logic' ] ] },
    { id: 'c7-2', sk: 's.rel', q: '第 (2) 格', o: [ 'which', 'that', 'it', 'what' ], why: '逗號後面補充說明前面整件事（蛾是淺色的），用 which；逗號後面不能用 that；用 it 會讓兩個句子只靠逗號連接。', st: [ [ '幫助蛾躲藏的是什麼？', '蛾是淺色的這件事', '深色的樹皮本身', '工業時代的煙霧', '淺色讓牠們能躲在淺色樹皮上。', 's.rel' ], [ '逗號後、指前面整件事，用？', 'which', 'that', 'what', '逗號後面不能用 that；what 不能接在句子後面當補充。', 's.rel' ] ] },
    { id: 'c7-3', sk: 'g.tense', q: '第 (3) 格', o: [ 'had become', 'have become', 'become', 'becoming' ], why: '說的是 1800 年代的事，而且「成為最常見」比「幾十年後」那個過去時間點更早完成，用過去完成式 had become。have become 是現在完成式，和過去的 1800s 不配。', st: [ [ '這件事發生在什麼時候？', '1800 年代，過去', '從過去一直到現在', '現在這個科技時代', 'When smoke… darkened the trees in the 1800s。', 'g.tense' ], [ 'within a few decades 表示什麼？', '到那時候已經完成', '還沒有開始', '一直持續到今天', '幾十年內已經變成最常見的類型。', 'g.tense' ], [ '過去某時之前已經完成，用？', 'had become', 'have become', 'become', '過去完成式 had＋過去分詞；have become 用在延續到現在。', 'g.tense' ] ] },
    { id: 'c7-4', sk: 'c.collo', q: '第 (4) 格', o: [ 'within', 'among', 'beside', 'toward' ], why: 'within a human lifetime＝在一個人的一生之內。within＋一段時間＝在…之內。', st: [ [ 'a human lifetime 是什麼？', '一段時間', '一個地點', '一群人', 'lifetime＝一生、壽命。', 'c.collo' ], [ '「在一段時間之內」用？', 'within', 'among', 'toward', 'within＋時間；among＝在…之中（三個以上的人或物）。', 'c.collo' ] ] },
    { id: 'c7-5', sk: 'v.mean', q: '第 (5) 格', o: [ 'vulnerable', 'resistant', 'comparable', 'appropriate' ], why: '依賴單一棲地或食物的物種，比較「容易受害」而滅絕：vulnerable to＝容易受…傷害（第 1 週學過）。resistant 意思相反。', st: [ [ '前一句說哪些物種過得好？', '繁殖快、適應力廣的', '依賴單一食物的', '體型最大的', 'Species that reproduce quickly and can live in a broad range of conditions… tend to do well。', 'c.logic' ], [ '依賴單一棲地的物種呢？', '比較容易滅絕', '比較不會滅絕', '和其他物種一樣', 'Those that depend on a single habitat… 和前一句對比。', 'c.logic' ], [ '「容易受害的」是？', 'vulnerable', 'resistant', 'comparable', 'vulnerable＝容易受傷害的；resistant＝有抵抗力的。', 'v.mean' ] ] }
  ]
},
   {
  type: 'read',
  title: 'Can Money Buy Happiness?',
  text: [ 'Does more money make people happier? For years, the best-known answer came from a 2010 study by two Nobel Prize winners, which found that Americans’ day-to-day happiness rose with income only up to about 75,000 dollars a year. Beyond that point, extra money seemed to make little difference to how people felt from moment to moment. Many newspapers summarized it with a simple message: beyond a certain point, money cannot buy happiness.', 'The finding was widely reported, and it fit a popular belief: that money matters when you are poor but not once your basic needs are met. In 2021, however, another researcher collected data from more than 30,000 working adults, who used a phone app to report their feelings at random times during the day. His results showed no such limit. Happiness continued to rise steadily with income, even among people earning several hundred thousand dollars.', 'Rather than continuing to argue, the two sides did something unusual: they worked together. Their joint study, published in 2023, found that both results were partly correct. The 2010 study had also used a different kind of question, which may explain part of the gap. For most people, happiness kept rising with income. For the unhappiest fifth of the population, however, it rose until about 100,000 dollars and then stopped, suggesting that beyond that point their problems could not be solved by money.', 'The debate offers a lesson that goes beyond economics. When two careful studies disagree, the answer is not always that one of them is wrong. Sometimes the difference reveals that an effect varies between groups of people, a possibility that researchers on both sides had failed to consider. Such cooperation between rivals, the author suggests, deserves to be far more common in science.' ],
  zh: '錢多會讓人比較快樂嗎？多年來，最有名的答案來自兩位諾貝爾獎得主在 2010 年的研究：美國人的日常快樂感只會隨收入增加到年收入約七萬五千美元；超過這個點，多出來的錢對人們每時每刻的感受似乎沒什麼影響。許多報紙用一句簡單的話總結：超過某個程度，錢買不到快樂。這個發現被廣泛報導，也符合一個普遍的看法：窮的時候錢很重要，但基本需求滿足後就不重要了。然而，2021 年另一位研究者蒐集了三萬多名在職成人的資料，他們用手機應用程式在一天中隨機的時間回報自己的感受。他的結果沒有顯示這樣的上限。快樂感隨著收入穩定上升，即使在年收入數十萬美元的人身上也是如此。雙方沒有繼續爭論，而是做了一件不尋常的事：他們合作了。他們在 2023 年發表的共同研究發現，兩邊的結果都部分正確。2010 年的研究用的問題形式也不一樣，這可能解釋了部分差距。對大多數人來說，快樂感隨收入持續上升。但對最不快樂的五分之一人口，快樂感上升到年收入約十萬美元就停了，這表示超過那個點，他們的問題不是錢能解決的。這場辯論帶來的教訓不只在經濟學。兩項嚴謹的研究結果不同時，答案不一定是其中一項錯了。有時候差異揭露的是：某個效果在不同族群之間不一樣，而這是雙方研究者都沒有考慮到的可能。作者認為，這種對手之間的合作在科學界應該更普遍。',
  qs: [
    { id: 'r7-1', sk: 'r.main', pre: '主旨：整篇文章最想說的事', q: 'What is the passage mainly about?', o: [ 'How two opposing studies on money and happiness were finally combined', 'Why people who earn more than 75,000 dollars are always unhappy', 'How a phone app was invented to measure people’s daily feelings', 'Why Nobel Prize winners are never wrong about questions of money' ], why: '第一、二段是兩個相反的研究，第三段說雙方合作得出兩邊都部分正確，第四段說這給科學的教訓。', st: [ [ '第一、二段是什麼關係？', '兩個結果相反的研究', '同一個研究的兩個部分', '研究和它的例子', '2010 年說有上限，2021 年說沒有上限。', 'r.main' ], [ '第三段發生了什麼？', '雙方合作，發現都部分正確', '其中一方承認資料造假', '兩方都決定放棄研究', 'they worked together… both results were partly correct。', 'r.main' ] ] },
    { id: 'r7-2', sk: 'r.locate', pre: '細節：2021 年的研究發現什麼', q: 'What did the 2021 study find?', o: [ 'Happiness kept rising with income without a clear limit.', 'Happiness stopped rising at about 75,000 dollars a year.', 'Happiness fell among people with very high incomes.', 'Happiness was not related to income in any way.' ], why: '第二段：His results showed no such limit. Happiness continued to rise steadily with income。', st: [ [ '答案在哪一段？', '第二段，In 2021 那句之後', '第一段，2010 study 那句', '第三段，2023 那句', '題目問 2021 年的研究。', 'r.locate' ], [ 'no such limit 指的是？', '沒有七萬五千美元的上限', '沒有找到任何受試者', '沒有使用手機應用程式', 'such limit＝前面說的 75,000 dollars 上限。', 'r.locate' ] ] },
    { id: 'r7-3', sk: 'r.para', pre: '換句話說：哪個選項和原文那句意思一樣', q: 'Which is closest in meaning to “their problems could not be solved by money”?', o: [ 'More money would not make them happier.', 'They needed much more money to be happy.', 'They had no problems related to money.', 'Money caused most of their problems.' ], why: '對最不快樂的人，收入超過十萬美元後快樂就不再上升：再多的錢也解決不了他們的問題。', st: [ [ '這句話說的是哪一群人？', '最不快樂的五分之一', '所有工作的美國人', '收入最高的一群人', 'For the unhappiest fifth of the population。', 'r.locate' ], [ '問題「不能用錢解決」表示？', '再多錢也不會更快樂', '需要更多錢才會快樂', '他們沒有任何問題', '快樂在十萬美元後就停了。', 'r.para' ] ] },
    { id: 'r7-4', sk: 'r.infer', pre: '推論：為什麼一開始結果不同', q: 'Why did the two studies seem to disagree at first?', o: [ 'The effect of income differed between groups of people.', 'One of the studies used false data on purpose.', 'The 2010 study included only very rich people.', 'People reported their feelings only once a year.' ], why: '第四段：the difference reveals that an effect varies between groups of people。最不快樂的人有上限，其他人沒有。', st: [ [ '共同研究發現兩邊的結果怎樣？', '都部分正確', '都完全錯誤', '只有 2010 年的對', 'both results were partly correct。', 'r.locate' ], [ '第四段怎麼解釋差異？', '效果在不同族群間不同', '其中一方的計算錯誤', '兩邊測量的時間不同', 'an effect varies between groups of people。', 'r.infer' ] ] },
    { id: 'r7-5', sk: 'r.attitude', pre: '作者態度：作者怎麼看雙方合作', q: 'How does the author view the researchers’ decision to work together?', o: [ 'Approving: it should happen more often', 'Critical: it wasted time and money', 'Doubtful: it produced no clear result', 'Neutral: the author gives no view' ], why: '最後一句：Such cooperation between rivals… deserves to be far more common in science。作者是贊同的。', st: [ [ '作者怎麼形容雙方的合作？', '不尋常，值得推廣', '浪費時間和經費', '沒有得出結果', 'did something unusual… deserves to be far more common。', 'r.attitude' ], [ 'deserves to be more common 表示作者？', '希望更多人這樣做', '希望大家別再這樣做', '不在乎有沒有人這樣做', 'deserve＝值得。', 'r.attitude' ] ] }
  ]
}],
];
